INSERT INTO `wp_postmeta` VALUES (462,102,'quote_block_0_photo','96');
INSERT INTO `wp_postmeta` VALUES (463,102,'_quote_block_0_photo','field_5d8bdf4caaf49');
INSERT INTO `wp_postmeta` VALUES (464,102,'quote_block_0_quote','I first started using Vasper a couple of years ago. I was excited to try it out, and learn about all the technology behind the product. Within 20 minutes of my first use, I had the endorphin rush that you can usually only achieve after a much longer workout. It helps with my recoveries after strenuous workouts on and off the ice during training. I don’t feel as tired, I sleep much better and just feel so much healthier and stronger overall since beginning to use Vasper. When I do vasper before my workouts I have some of my best workouts. I can maybe compare it to like a runner’s high. It’s unbelievable.');
INSERT INTO `wp_postmeta` VALUES (465,102,'_quote_block_0_quote','field_5d8bdf27aaf47');
INSERT INTO `wp_postmeta` VALUES (466,102,'quote_block_0_author','PATRICK MARLEAU -  NHL, OLYMPIC GOLD MEDALIST');
INSERT INTO `wp_postmeta` VALUES (467,102,'_quote_block_0_author','field_5d8bdf3daaf48');
INSERT INTO `wp_postmeta` VALUES (468,102,'quote_block_1_photo','95');
INSERT INTO `wp_postmeta` VALUES (469,102,'_quote_block_1_photo','field_5d8bdf4caaf49');
INSERT INTO `wp_postmeta` VALUES (470,102,'quote_block_1_quote','The science and technology of Vasper is light years ahead of its time. It has tremendous potential to revolutionize how we address strength training and rehabilitation.');
INSERT INTO `wp_postmeta` VALUES (471,102,'_quote_block_1_quote','field_5d8bdf27aaf47');
INSERT INTO `wp_postmeta` VALUES (472,102,'quote_block_1_author','DARRYL KAN MD - ORTHOPEDIC SURGEON, QUEENS MEDICAL CENTER HAWAII, FORMER NFL QUARTERBACK');
INSERT INTO `wp_postmeta` VALUES (473,102,'_quote_block_1_author','field_5d8bdf3daaf48');
