INSERT INTO `wp_postmeta` VALUES (476,103,'_edit_lock','1597343630:1');
INSERT INTO `wp_postmeta` VALUES (477,104,'quote_block_0_photo','76');
INSERT INTO `wp_postmeta` VALUES (478,104,'_quote_block_0_photo','field_5d8bdf4caaf49');
INSERT INTO `wp_postmeta` VALUES (479,104,'quote_block_0_quote','I have been fighting through injuries for quite some time. Since starting this workout, I have noticed significant changes in the amount of pain that I feel. I’ve had no inflammation in any joints and I no longer notice much knee pain at all, or aches in my foot or ankle. This workout truly is helping my body to heal itself.');
INSERT INTO `wp_postmeta` VALUES (480,104,'_quote_block_0_quote','field_5d8bdf27aaf47');
INSERT INTO `wp_postmeta` VALUES (481,104,'quote_block_0_author','JAYNE APPEL - WNBA ALL-STAR');
INSERT INTO `wp_postmeta` VALUES (482,104,'_quote_block_0_author','field_5d8bdf3daaf48');
INSERT INTO `wp_postmeta` VALUES (483,104,'quote_block_1_photo','75');
INSERT INTO `wp_postmeta` VALUES (484,104,'_quote_block_1_photo','field_5d8bdf4caaf49');
INSERT INTO `wp_postmeta` VALUES (485,104,'quote_block_1_quote','On March 7, 2011, I suffered a traumatic injury to my right ankle. I was told I would never run again. A year later, I posted the top triple jump distance in the US. I feel confident adding Vasper to my standard rehabilitation program helped me beat the odds of my injury and helped me to recover faster than any of my doctors expected. My time at Vasper has renewed my hope of competing. Thank you for believing in my dreams!');
INSERT INTO `wp_postmeta` VALUES (486,104,'_quote_block_1_quote','field_5d8bdf27aaf47');
INSERT INTO `wp_postmeta` VALUES (487,104,'quote_block_1_author','ERICA ASHLEY MCLAIN - US OLYMPIC TRACK & FIELD ATHLETE');
INSERT INTO `wp_postmeta` VALUES (488,104,'_quote_block_1_author','field_5d8bdf3daaf48');
INSERT INTO `wp_postmeta` VALUES (489,104,'quote_block','2');
INSERT INTO `wp_postmeta` VALUES (490,104,'_quote_block','field_5d8bdf10aaf46');
INSERT INTO `wp_postmeta` VALUES (491,104,'hero_title','REHABILITATION REINVENTED');
INSERT INTO `wp_postmeta` VALUES (492,104,'_hero_title','field_5da786a8a7b24');
INSERT INTO `wp_postmeta` VALUES (493,104,'hero_text','At Vasper, we believe that the best medicine doesn’t always come in a bottle. We believe in body’s extraordinary natural ability to heal itself. Amplify your body’s biological repair and recovery response with our accessible, sweat-free, and low-impact 21-minute workout sessions designed to help you heal faster. Research hospitals, physicians, physical therapists, injured athletes, and more are using Vasper with impressive results. Go on; see for yourself what all of the hype is about.');
