INSERT INTO `wp_postmeta` VALUES (1043,134,'_menu_item_url','');
INSERT INTO `wp_postmeta` VALUES (1050,139,'new_faq_0_answer','We advise hydrating and eating a balanced meal 1-2 hours before your first Vasper session or staying with your usual nutrition routine pre-exercise.');
INSERT INTO `wp_postmeta` VALUES (1051,139,'_new_faq_0_answer','field_5dadfc35f6822');
INSERT INTO `wp_postmeta` VALUES (1052,139,'new_faq_1_question','What should I wear?');
INSERT INTO `wp_postmeta` VALUES (1053,139,'_new_faq_1_question','field_5dadfc15f6821');
INSERT INTO `wp_postmeta` VALUES (1054,139,'new_faq_1_answer','Normal exercise attire is fine! We recommend a shirt with sleeves and shorts, as well as avoiding exercise tights that are too compressive or slick. The workout is performed barefoot so there is no need to have athletic footwear.');
INSERT INTO `wp_postmeta` VALUES (1055,139,'_new_faq_1_answer','field_5dadfc35f6822');
INSERT INTO `wp_postmeta` VALUES (1056,139,'new_faq_2_question','Why am I barefoot?');
INSERT INTO `wp_postmeta` VALUES (1057,139,'_new_faq_2_question','field_5dadfc15f6821');
INSERT INTO `wp_postmeta` VALUES (1058,139,'new_faq_2_answer','You are barefoot during your Vasper session because we are cooling your feet! The bottom of your feet are one of the most effective areas of the body for heat exchange, so by cooling the soles of your feet, the heat generated by your body is released, which helps you stay comfortably cool and minimize sweating.');
INSERT INTO `wp_postmeta` VALUES (1059,139,'_new_faq_2_answer','field_5dadfc35f6822');
INSERT INTO `wp_postmeta` VALUES (1060,139,'new_faq_3_question','Why is it so cold?');
INSERT INTO `wp_postmeta` VALUES (1061,139,'_new_faq_3_question','field_5dadfc15f6821');
INSERT INTO `wp_postmeta` VALUES (1062,139,'new_faq_3_answer','Vasper uses cooling not only to keep you comfortable during your workout, but also to increase your exercise efficiency and increase performance. During exercise, blood is shunted from working muscles to the surface of the skin to help cool the body down, reducing muscles’ capacity as oxygen is carried away from muscles with the blood. Vasper avoids this problem by using cooling, which allows oxygen-carrying blood to remain in the muscles, resulting in enhanced muscular function.');
INSERT INTO `wp_postmeta` VALUES (1063,139,'_new_faq_3_answer','field_5dadfc35f6822');
INSERT INTO `wp_postmeta` VALUES (1064,139,'new_faq_4_question','Who uses Vasper?');
INSERT INTO `wp_postmeta` VALUES (1065,139,'_new_faq_4_question','field_5dadfc15f6821');
INSERT INTO `wp_postmeta` VALUES (1066,139,'new_faq_4_answer','If you can benefit from exercise then you can benefit from Vasper! Our software is customizable so your Vasper session will be tailored to fit your level of fitness, endurance and goals. You can expect to see professional athletes, senior citizens, those with severe disabilities, veterans, and even your neighbor who is just looking to elevate their health and fitness at our Vasper HQ. All are welcome. If you have specific questions regarding special conditions or inquires please contact the Vasper HQ front desk at (650) 776-0296.');
INSERT INTO `wp_postmeta` VALUES (1067,139,'_new_faq_4_answer','field_5dadfc35f6822');
INSERT INTO `wp_postmeta` VALUES (1068,139,'new_faq_5_question','Will I be sore after my Vasper session?');
INSERT INTO `wp_postmeta` VALUES (1069,139,'_new_faq_5_question','field_5dadfc15f6821');
INSERT INTO `wp_postmeta` VALUES (1070,139,'new_faq_5_answer','Most Vasper users report no muscle soreness following their session. Vasper is designed to be a moderate, low-impact, non-damaging exercise session which still delivers the benefits of an intensive workout.');
INSERT INTO `wp_postmeta` VALUES (1071,139,'_new_faq_5_answer','field_5dadfc35f6822');
INSERT INTO `wp_postmeta` VALUES (1072,139,'new_faq_6_question','Can I workout before or after my Vasper session?');
INSERT INTO `wp_postmeta` VALUES (1073,139,'_new_faq_6_question','field_5dadfc15f6821');
INSERT INTO `wp_postmeta` VALUES (1074,139,'new_faq_6_answer','As a moderate exertion exercise, Vasper can be used as a substitute or complement to your current exercise regime. Vasper can supplement your workout by promoting performance gains, improving recovery, and expediting rehabilitation.');
INSERT INTO `wp_postmeta` VALUES (1075,139,'_new_faq_6_answer','field_5dadfc35f6822');
INSERT INTO `wp_postmeta` VALUES (1076,139,'new_faq_7_question','Why do I have to cool down after my Vasper session?');
INSERT INTO `wp_postmeta` VALUES (1077,139,'_new_faq_7_question','field_5dadfc15f6821');
INSERT INTO `wp_postmeta` VALUES (1078,139,'new_faq_7_answer','After your Vasper session you will lay on a cooling pad for 5-15 minutes. This time allows your heart rate and breathing to return to your resting rates and acts as relaxing transition between the Vasper session and the rest of your day. The cooling also aids in recovery from inflammation, pain, or soreness.');
INSERT INTO `wp_postmeta` VALUES (1079,139,'_new_faq_7_answer','field_5dadfc35f6822');
INSERT INTO `wp_postmeta` VALUES (1080,139,'new_faq','9');
INSERT INTO `wp_postmeta` VALUES (1081,139,'_new_faq','field_5dadfbfaf6820');
INSERT INTO `wp_postmeta` VALUES (1082,141,'new_faq_0_question','Should I have something to eat before my Vasper session?');
INSERT INTO `wp_postmeta` VALUES (1083,141,'_new_faq_0_question','field_5dadfc15f6821');
INSERT INTO `wp_postmeta` VALUES (1084,141,'new_faq_0_answer','We advise hydrating and eating a balanced meal 1-2 hours before your first Vasper session or staying with your usual nutrition routine pre-exercise.');
INSERT INTO `wp_postmeta` VALUES (1085,141,'_new_faq_0_answer','field_5dadfc35f6822');
