INSERT INTO `wp_postmeta` VALUES (2748,320,'tab_1_children_tab_name_1','Hormones');
INSERT INTO `wp_postmeta` VALUES (2749,320,'_tab_1_children_tab_name_1','field_5db89b89740ef');
INSERT INTO `wp_postmeta` VALUES (2750,320,'tab_1_children_top_paragraph_1','Hormones are your body’s systemic signaling molecules and are released in different areas of the body and move through the circulatory system to regulate your body’s function and behavior. Hormones affect the body in many different ways and have significant impacts on function, form, and feel. ');
INSERT INTO `wp_postmeta` VALUES (2751,320,'_tab_1_children_top_paragraph_1','field_5db89bc1740f3');
INSERT INTO `wp_postmeta` VALUES (2752,320,'tab_1_children_tab_name_2','Stem Cells');
INSERT INTO `wp_postmeta` VALUES (2753,320,'_tab_1_children_tab_name_2','field_5db89ba9740f1');
INSERT INTO `wp_postmeta` VALUES (2754,320,'tab_1_children_top_paragraph_2','You’ve probably heard about stem cells in many different contexts. Stem cells are used in surgery, rehabilitation, medical devices, outpatient treatments, cosmetology, and dermatology.');
INSERT INTO `wp_postmeta` VALUES (2755,320,'_tab_1_children_top_paragraph_2','field_5db89beb740f6');
INSERT INTO `wp_postmeta` VALUES (2756,320,'tab_1_children_tab_name_3','Cardiovascular');
INSERT INTO `wp_postmeta` VALUES (2757,320,'_tab_1_children_tab_name_3','field_5db89bae740f2');
INSERT INTO `wp_postmeta` VALUES (2758,320,'tab_1_children_top_paragraph_3','Vasper puts safety first. Before starting our clinical trial in cardiopulmonary rehabilitation, cardiologist Dr. Jeff Gladden wished to determine that Vasper does not cause a response that is different than conventional exercise.');
