INSERT INTO `wp_postmeta` VALUES (4831,595,'_quote_block_1_photo','field_5d8bdf4caaf49');
INSERT INTO `wp_postmeta` VALUES (4832,595,'quote_block_1_quote','The science and technology of Vasper is light years ahead of its time. It has tremendous potential to revolutionize how we address strength training and rehabilitation.');
