INSERT INTO `wp_postmeta` VALUES (4834,595,'quote_block_1_author','DARRYL KAN MD - ORTHOPEDIC SURGEON, QUEENS MEDICAL CENTER HAWAII, FORMER NFL QUARTERBACK');
INSERT INTO `wp_postmeta` VALUES (4835,595,'_quote_block_1_author','field_5d8bdf3daaf48');
