INSERT INTO `wp_postmeta` VALUES (5632,608,'hero_title','The Research');
INSERT INTO `wp_postmeta` VALUES (5633,608,'_hero_title','field_5db868eb4de19');
INSERT INTO `wp_postmeta` VALUES (5634,608,'hero_paragraph','Vasper is a patented health technology designed to promote systemic health gains. \r\n\r\nOur mission is to provide non-invasive technology solutions that allow people to actively engage their body’s natural systems in achieving optimal health and wellness. \r\n\r\nTherefore we are dedicated to developing research studies that can help us understand how Vasper works and how it can affect people of all ages, ability levels and health statuses. We are have partnered with researchers and institutions around the world to examine hypotheses and produce rigorous scientific support for our theories. ');
INSERT INTO `wp_postmeta` VALUES (5635,608,'_hero_paragraph','field_5db869004de1a');
INSERT INTO `wp_postmeta` VALUES (5636,608,'tab_name1','Physical Benefits');
INSERT INTO `wp_postmeta` VALUES (5637,608,'_tab_name1','field_5db87c7eb729c');
INSERT INTO `wp_postmeta` VALUES (5638,608,'tab_1_paragraph','To understand the physical benefits Vasper provides, we’ve reviewed research studies of three key components – hormones, stem cells, and cardiovascular health – that play a major role individually & together in the body’s functionality. Safety always comes first, which is Vasper partners with top to study the impact of VC3 technology on the body. From hormones to stem cell growth we ensure that you are comprehensively equipped with knowledge use and get the most out of VC3 process.');
INSERT INTO `wp_postmeta` VALUES (5639,608,'_tab_1_paragraph','field_5db886deaed03');
