INSERT INTO `wp_postmeta` VALUES (5656,608,'tab_name2','Lifestyle & Wellness Benefits');
INSERT INTO `wp_postmeta` VALUES (5657,608,'_tab_name2','field_5db87c8eb729d');
INSERT INTO `wp_postmeta` VALUES (5658,608,'tab_2_paragraph','At any age, you deserve to feel great – and that feeling should come easy. We’ve partnered with various individuals, from U.S. war veterans to independent living seniors, to understand the benefits of Vasper when it comes to sleep quality and emotional well-being. Using our non-invasive technology, our goal is to fully comprehend how individuals at any age or life experience can engage their body and achieve optimal energy levels & wellness.');
