INSERT INTO `wp_postmeta` VALUES (6222,160,'hero_subtitle','At Vasper, we strive to advance the health and wellness of our troops in service and those returning from service. We are always researching better ways to help all recover better and faster with Vasper. Vasper\'s technology helps veteran\'s combat injury, rehab quicker, and reach their wellness goals.');
INSERT INTO `wp_postmeta` VALUES (6221,640,'_wp_old_date','2020-02-12');
