INSERT INTO `wp_postmeta` VALUES (6449,649,'_quote_block_1_photo','field_5d8bdf4caaf49');
INSERT INTO `wp_postmeta` VALUES (6450,649,'quote_block_1_quote','The science and technology of Vasper is light years ahead of its time. It has tremendous potential to revolutionize how we address strength training and rehabilitation.');
