INSERT INTO `wp_postmeta` VALUES (9120,12,'_quote_block_2_photo','field_5d8bdf4caaf49');
INSERT INTO `wp_postmeta` VALUES (9121,12,'quote_block_2_quote','The VASPER is, bar none, the most efficient and effective exercise machine I have ever used\r\nin my life. When it comes to time-hacking and getting the equivalent of hours and hours of\r\nexercise in just twenty-one freakin’ minutes, absolutely nothing beats this thing. I can build\r\nstrength and cardio all in one fast dose, and better yet, feel an amazing surge of growth\r\nhormone and testosterone afterwards that sticks with me the entire day!');
INSERT INTO `wp_postmeta` VALUES (9122,12,'_quote_block_2_quote','field_5d8bdf27aaf47');
INSERT INTO `wp_postmeta` VALUES (9123,12,'quote_block_2_author','<strong>Ben Greenfield</strong>\r\n\r\n<br/>Personal Trainer, Holistic Nutritionist and Health Expert');
INSERT INTO `wp_postmeta` VALUES (13337,12,'quote_block_2_author_title','Personal Trainer, Holistic Nutritionist And Health Expert');
INSERT INTO `wp_postmeta` VALUES (9209,705,'quote_block_0_photo','26');
