INSERT INTO `wp_postmeta` VALUES (9125,12,'quote_block_3_photo','701');
INSERT INTO `wp_postmeta` VALUES (9126,12,'_quote_block_3_photo','field_5d8bdf4caaf49');
INSERT INTO `wp_postmeta` VALUES (9127,12,'quote_block_3_quote','Over the first 15 months of using Vasper more than 3x weekly, I’ve gained 6 pounds of muscle,\r\nlost 14 pounds of fat, increased my testosterone score from 379 to 697, and have enjoyed the\r\nmost relaxed, energized, creative and productive period of my life. All of this at age 72. My\r\nsuccess story has so far persuaded 100+ other Strategic Coach e ntrepreneurs to purchase\r\ntheir own Vasper.');
INSERT INTO `wp_postmeta` VALUES (9128,12,'_quote_block_3_quote','field_5d8bdf27aaf47');
INSERT INTO `wp_postmeta` VALUES (9129,12,'quote_block_3_author','<strong>Dan Sullivan</strong>\r\n\r\n<br/>Co-founder, Strategic Coach');
INSERT INTO `wp_postmeta` VALUES (13339,12,'quote_block_3_author_title','Co-founder, Strategic Coach');
INSERT INTO `wp_postmeta` VALUES (9130,12,'_quote_block_3_author','field_5d8bdf3daaf48');
INSERT INTO `wp_postmeta` VALUES (9131,702,'quote_block_0_photo','26');
INSERT INTO `wp_postmeta` VALUES (9132,702,'_quote_block_0_photo','field_5d8bdf4caaf49');
INSERT INTO `wp_postmeta` VALUES (9133,702,'quote_block_0_quote','When I can replace 2 1⁄2 hours of cardio with 21 minutes of work, without needing to shower afterward, all the barriers to exercise drop away. Plus, it works even better. I totally love my Vasper!');
INSERT INTO `wp_postmeta` VALUES (9134,702,'_quote_block_0_quote','field_5d8bdf27aaf47');
INSERT INTO `wp_postmeta` VALUES (9135,702,'quote_block_0_author','Dave Asprey - Founder, Bulletproof');
INSERT INTO `wp_postmeta` VALUES (9136,702,'_quote_block_0_author','field_5d8bdf3daaf48');
INSERT INTO `wp_postmeta` VALUES (9137,702,'quote_block_1_photo','27');
