INSERT INTO `wp_postmeta` VALUES (9377,710,'quote_block_0_photo','76');
INSERT INTO `wp_postmeta` VALUES (9378,710,'_quote_block_0_photo','field_5d8bdf4caaf49');
INSERT INTO `wp_postmeta` VALUES (9379,710,'quote_block_0_quote','I have been fighting through injuries for quite some time. Since starting this workout, I have noticed significant changes in the amount of pain that I feel. I’ve had no inflammation in any joints and I no longer notice much knee pain at all, or aches in my foot or ankle. This workout truly is helping my body to heal itself.');
INSERT INTO `wp_postmeta` VALUES (9380,710,'_quote_block_0_quote','field_5d8bdf27aaf47');
INSERT INTO `wp_postmeta` VALUES (9381,710,'quote_block_0_author','JAYNE APPEL - WNBA ALL-STAR');
INSERT INTO `wp_postmeta` VALUES (9382,710,'_quote_block_0_author','field_5d8bdf3daaf48');
INSERT INTO `wp_postmeta` VALUES (9383,710,'quote_block_1_photo','75');
INSERT INTO `wp_postmeta` VALUES (9384,710,'_quote_block_1_photo','field_5d8bdf4caaf49');
INSERT INTO `wp_postmeta` VALUES (9385,710,'quote_block_1_quote','On March 7, 2011, I suffered a traumatic injury to my right ankle. I was told I would never run again. A year later, I posted the top triple jump distance in the US. I feel confident adding Vasper to my standard rehabilitation program helped me beat the odds of my injury and helped me to recover faster than any of my doctors expected. My time at Vasper has renewed my hope of competing. Thank you for believing in my dreams!');
INSERT INTO `wp_postmeta` VALUES (9386,710,'_quote_block_1_quote','field_5d8bdf27aaf47');
INSERT INTO `wp_postmeta` VALUES (9387,710,'quote_block_1_author','ERICA ASHLEY MCLAIN - US OLYMPIC TRACK & FIELD ATHLETE');
INSERT INTO `wp_postmeta` VALUES (9388,710,'_quote_block_1_author','field_5d8bdf3daaf48');
INSERT INTO `wp_postmeta` VALUES (9389,710,'quote_block','3');
INSERT INTO `wp_postmeta` VALUES (9390,710,'_quote_block','field_5d8bdf10aaf46');
INSERT INTO `wp_postmeta` VALUES (9391,710,'hero_title','REHABILITATION REINVENTED');
INSERT INTO `wp_postmeta` VALUES (9392,710,'_hero_title','field_5da786a8a7b24');
INSERT INTO `wp_postmeta` VALUES (9393,710,'hero_text','At Vasper, we believe in the body’s extraordinary natural ability to heal itself. Our accessible, sweat-free, and low-impact 21-minute workout sessions mimic the physiology of an intensive workout to create better outcomes early on in the rehabilitation process. For anyone who lacks the physical capacity to engage in exercise, our programs provide a set of benefits that would be entirely out of reach otherwise. See for yourself why MDs, physical therapists, and more are recommending Vasper to their patients!');
