INSERT INTO `wp_postmeta` VALUES (11902,751,'quote_block_0_quote','I have been fighting through injuries for quite some time. Since starting this workout, I have noticed significant changes in the amount of pain that I feel. I’ve had no inflammation in any joints and I no longer notice much knee pain at all, or aches in my foot or ankle. This workout truly is helping my body to heal itself.');
INSERT INTO `wp_postmeta` VALUES (11903,751,'_quote_block_0_quote','field_5d8bdf27aaf47');
INSERT INTO `wp_postmeta` VALUES (11904,751,'quote_block_0_author','JAYNE APPEL - WNBA ALL-STAR');
INSERT INTO `wp_postmeta` VALUES (11905,751,'_quote_block_0_author','field_5d8bdf3daaf48');
INSERT INTO `wp_postmeta` VALUES (11906,751,'quote_block_1_photo','75');
INSERT INTO `wp_postmeta` VALUES (11907,751,'_quote_block_1_photo','field_5d8bdf4caaf49');
INSERT INTO `wp_postmeta` VALUES (11908,751,'quote_block_1_quote','On March 7, 2011, I suffered a traumatic injury to my right ankle. I was told I would never run again. A year later, I posted the top triple jump distance in the US. I feel confident adding Vasper to my standard rehabilitation program helped me beat the odds of my injury and helped me to recover faster than any of my doctors expected. My time at Vasper has renewed my hope of competing. Thank you for believing in my dreams!');
INSERT INTO `wp_postmeta` VALUES (11909,751,'_quote_block_1_quote','field_5d8bdf27aaf47');
INSERT INTO `wp_postmeta` VALUES (11910,751,'quote_block_1_author','ERICA ASHLEY MCLAIN - US OLYMPIC TRACK & FIELD ATHLETE');
INSERT INTO `wp_postmeta` VALUES (11911,751,'_quote_block_1_author','field_5d8bdf3daaf48');
