INSERT INTO `wp_postmeta` VALUES (13301,790,'quote_block_0_quote','When I can replace 2 1⁄2 hours of cardio with 21 minutes of work, without needing to shower afterward, all the barriers to exercise drop away. Plus, it works even better. I totally love my Vasper!');
INSERT INTO `wp_postmeta` VALUES (13302,790,'_quote_block_0_quote','field_5d8bdf27aaf47');
INSERT INTO `wp_postmeta` VALUES (13303,790,'quote_block_0_author','Dave Asprey - Founder, Bulletproof');
INSERT INTO `wp_postmeta` VALUES (13304,790,'_quote_block_0_author','field_5d8bdf3daaf48');
INSERT INTO `wp_postmeta` VALUES (13305,790,'quote_block_1_photo','27');
INSERT INTO `wp_postmeta` VALUES (13306,790,'_quote_block_1_photo','field_5d8bdf4caaf49');
INSERT INTO `wp_postmeta` VALUES (13307,790,'quote_block_1_quote','Vasper is my force multiplier tool to achieve optimum fitness, sleep, and vitality without overtraining. I get the benefit of 2 hours of intense exercise in just 21 minutes of low impact workout. The core cooling aspect of Vasper enables me to fully recover in 10 minutes while delivering more oxygen to my body and brain. I love my Vasper, and it’s now a regular part of my priming routine for success.');
