INSERT INTO `wp_postmeta` VALUES (14452,803,'_summary_title','field_5dcc6bf0b1cdc');
INSERT INTO `wp_postmeta` VALUES (14453,803,'summary_bullets_0_bullet_image','408');
INSERT INTO `wp_postmeta` VALUES (14454,803,'_summary_bullets_0_bullet_image','field_5dcc6cb55ed5e');
INSERT INTO `wp_postmeta` VALUES (14455,803,'summary_bullets_0_bullet_title','Physical');
INSERT INTO `wp_postmeta` VALUES (14456,803,'_summary_bullets_0_bullet_title','field_5dcc6cc25ed5f');
INSERT INTO `wp_postmeta` VALUES (14457,803,'summary_bullets_0_bullet_text','Vasper is based on three scientifically proven principles – compression technology, cooling and interval training. When all principles are working together, the results are extraordinary. Compression and cooling create the effect of high intensity (anaerobic) exercise without the time, effort, and muscle damage it takes to achieve the same results with conventional exercise.');
INSERT INTO `wp_postmeta` VALUES (14458,803,'_summary_bullets_0_bullet_text','field_5dcc6cd55ed60');
INSERT INTO `wp_postmeta` VALUES (14459,803,'summary_bullets_1_bullet_image','409');
INSERT INTO `wp_postmeta` VALUES (14460,803,'_summary_bullets_1_bullet_image','field_5dcc6cb55ed5e');
INSERT INTO `wp_postmeta` VALUES (14461,803,'summary_bullets_1_bullet_title','Attire');
INSERT INTO `wp_postmeta` VALUES (14462,803,'_summary_bullets_1_bullet_title','field_5dcc6cc25ed5f');
INSERT INTO `wp_postmeta` VALUES (14463,803,'summary_bullets_1_bullet_text','Normal exercise attire is fine! We recommend a shirt with sleeves and shorts, as well as avoiding exercise tights that are too compressive or slick. The workout is performed barefoot so there is no need to have athletic footwear.');
INSERT INTO `wp_postmeta` VALUES (14464,803,'_summary_bullets_1_bullet_text','field_5dcc6cd55ed60');
INSERT INTO `wp_postmeta` VALUES (14465,803,'summary_bullets_2_bullet_image','410');
INSERT INTO `wp_postmeta` VALUES (14466,803,'_summary_bullets_2_bullet_image','field_5dcc6cb55ed5e');
INSERT INTO `wp_postmeta` VALUES (14467,803,'summary_bullets_2_bullet_title','Shoes');
INSERT INTO `wp_postmeta` VALUES (14468,803,'_summary_bullets_2_bullet_title','field_5dcc6cc25ed5f');
INSERT INTO `wp_postmeta` VALUES (14469,803,'summary_bullets_2_bullet_text','No shoes needed! You are barefoot during your Vasper session because we are cooling your feet! The bottom of your feet is one of the most effective areas of the body for heat exchange, so by cooling the soles of your feet, the heat generated by your body is released, which helps you stay comfortably cool and minimize sweating.');
INSERT INTO `wp_postmeta` VALUES (14470,803,'_summary_bullets_2_bullet_text','field_5dcc6cd55ed60');
