INSERT INTO `wp_postmeta` VALUES (14575,804,'summary_bullets_1_bullet_text','Normal exercise attire is fine! We recommend a shirt with sleeves and shorts, as well as avoiding exercise tights that are too compressive or slick. The workout is performed barefoot so there is no need to have athletic footwear.');
