INSERT INTO `wp_postmeta` VALUES (14580,804,'_summary_bullets_2_bullet_title','field_5dcc6cc25ed5f');
INSERT INTO `wp_postmeta` VALUES (14581,804,'summary_bullets_2_bullet_text','No shoes needed! You are barefoot during your Vasper session because we are cooling your feet! The bottom of your feet is one of the most effective areas of the body for heat exchange, so by cooling the soles of your feet, the heat generated by your body is released, which helps you stay comfortably cool and minimize sweating.');
