INSERT INTO `wp_postmeta` VALUES (14587,804,'summary_bullets_3_bullet_text','Vasper focused on 21-minute sessions, in which you will complete a low-impact high-intensity workout. Replacing all the work that you would normally do in longer workouts with other programs you can get in a customizable program with Vasper’s NuStep T5XR platform. Vasper leaves you energized and rejuvenated, alleviating your body aches and pains.');
INSERT INTO `wp_postmeta` VALUES (14588,804,'_summary_bullets_3_bullet_text','field_5dcc6cd55ed60');
