INSERT INTO `wp_postmeta` VALUES (14591,804,'summary_bullets_4_bullet_title','End of Session');
INSERT INTO `wp_postmeta` VALUES (14592,804,'_summary_bullets_4_bullet_title','field_5dcc6cc25ed5f');
INSERT INTO `wp_postmeta` VALUES (14593,804,'summary_bullets_4_bullet_text','After your Vasper session, you will lay on a cooling pad for 5-15 minutes. This time allows your heart rate and breathing to return to your resting rates and acts as a relaxing transition between the Vasper session and the rest of your day. The cooling also aids in recovery from inflammation, pain, or soreness. Most Vasper users report no muscle soreness following their session. Vasper is designed to be a moderate, low-impact, non-damaging exercise session that still delivers the benefits of an intensive workout.');
INSERT INTO `wp_postmeta` VALUES (14594,804,'_summary_bullets_4_bullet_text','field_5dcc6cd55ed60');
