INSERT INTO `wp_postmeta` VALUES (17384,870,'quote_block_1_photo','75');
INSERT INTO `wp_postmeta` VALUES (17385,870,'_quote_block_1_photo','field_5d8bdf4caaf49');
INSERT INTO `wp_postmeta` VALUES (17386,870,'quote_block_1_quote','On March 7, 2011, I suffered a traumatic injury to my right ankle. I was told I would never run again. A year later, I posted the top triple jump distance in the US. I feel confident adding Vasper to my standard rehabilitation program helped me beat the odds of my injury and helped me to recover faster than any of my doctors expected. My time at Vasper has renewed my hope of competing. Thank you for believing in my dreams!');
INSERT INTO `wp_postmeta` VALUES (17387,870,'_quote_block_1_quote','field_5d8bdf27aaf47');
