INSERT INTO `wp_postmeta` VALUES (18899,912,'summary_title','What You Need to Know');
INSERT INTO `wp_postmeta` VALUES (18900,912,'_summary_title','field_5dcc6bf0b1cdc');
INSERT INTO `wp_postmeta` VALUES (18901,912,'summary_bullets_0_bullet_image','408');
INSERT INTO `wp_postmeta` VALUES (18902,912,'_summary_bullets_0_bullet_image','field_5dcc6cb55ed5e');
INSERT INTO `wp_postmeta` VALUES (18903,912,'summary_bullets_0_bullet_title','Physical');
INSERT INTO `wp_postmeta` VALUES (18904,912,'_summary_bullets_0_bullet_title','field_5dcc6cc25ed5f');
INSERT INTO `wp_postmeta` VALUES (18905,912,'summary_bullets_0_bullet_text','Vasper is based on three scientifically proven principles – compression technology, cooling and interval training. When all principles are working together, the results are extraordinary. Compression and cooling create the effect of high intensity (anaerobic) exercise without the time, effort, and muscle damage it takes to achieve the same results with conventional exercise.');
INSERT INTO `wp_postmeta` VALUES (18906,912,'_summary_bullets_0_bullet_text','field_5dcc6cd55ed60');
INSERT INTO `wp_postmeta` VALUES (18907,912,'summary_bullets_1_bullet_image','409');
INSERT INTO `wp_postmeta` VALUES (18908,912,'_summary_bullets_1_bullet_image','field_5dcc6cb55ed5e');
INSERT INTO `wp_postmeta` VALUES (18909,912,'summary_bullets_1_bullet_title','Attire');
INSERT INTO `wp_postmeta` VALUES (18910,912,'_summary_bullets_1_bullet_title','field_5dcc6cc25ed5f');
INSERT INTO `wp_postmeta` VALUES (18911,912,'summary_bullets_1_bullet_text','Normal exercise attire is fine! We recommend a shirt with sleeves and shorts, as well as avoiding exercise tights that are too compressive or slick. The workout is performed barefoot so there is no need to have athletic footwear.');
INSERT INTO `wp_postmeta` VALUES (18912,912,'_summary_bullets_1_bullet_text','field_5dcc6cd55ed60');
INSERT INTO `wp_postmeta` VALUES (18913,912,'summary_bullets_2_bullet_image','410');
INSERT INTO `wp_postmeta` VALUES (18914,912,'_summary_bullets_2_bullet_image','field_5dcc6cb55ed5e');
INSERT INTO `wp_postmeta` VALUES (18915,912,'summary_bullets_2_bullet_title','Shoes');
INSERT INTO `wp_postmeta` VALUES (18916,912,'_summary_bullets_2_bullet_title','field_5dcc6cc25ed5f');
INSERT INTO `wp_postmeta` VALUES (18917,912,'summary_bullets_2_bullet_text','No shoes needed! You are barefoot during your Vasper session because we are cooling your feet! The bottom of your feet is one of the most effective areas of the body for heat exchange, so by cooling the soles of your feet, the heat generated by your body is released, which helps you stay comfortably cool and minimize sweating.');
INSERT INTO `wp_postmeta` VALUES (18918,912,'_summary_bullets_2_bullet_text','field_5dcc6cd55ed60');
INSERT INTO `wp_postmeta` VALUES (18919,912,'summary_bullets_3_bullet_image','411');
INSERT INTO `wp_postmeta` VALUES (18920,912,'_summary_bullets_3_bullet_image','field_5dcc6cb55ed5e');
INSERT INTO `wp_postmeta` VALUES (18921,912,'summary_bullets_3_bullet_title','Time');
INSERT INTO `wp_postmeta` VALUES (18922,912,'_summary_bullets_3_bullet_title','field_5dcc6cc25ed5f');
INSERT INTO `wp_postmeta` VALUES (18923,912,'summary_bullets_3_bullet_text','Vasper focused on 21-minute sessions, in which you will complete a low-impact high-intensity workout. Replacing all the work that you would normally do in longer workouts with other programs you can get in a customizable program with Vasper’s NuStep T5XR platform. Vasper leaves you energized and rejuvenated, alleviating your body aches and pains.');
INSERT INTO `wp_postmeta` VALUES (18924,912,'_summary_bullets_3_bullet_text','field_5dcc6cd55ed60');
INSERT INTO `wp_postmeta` VALUES (18925,912,'summary_bullets_4_bullet_image','412');
INSERT INTO `wp_postmeta` VALUES (18926,912,'_summary_bullets_4_bullet_image','field_5dcc6cb55ed5e');
INSERT INTO `wp_postmeta` VALUES (18927,912,'summary_bullets_4_bullet_title','End of Session');
INSERT INTO `wp_postmeta` VALUES (18928,912,'_summary_bullets_4_bullet_title','field_5dcc6cc25ed5f');
INSERT INTO `wp_postmeta` VALUES (18929,912,'summary_bullets_4_bullet_text','After your Vasper session, you will lay on a cooling pad for 5-15 minutes. This time allows your heart rate and breathing to return to your resting rates and acts as a relaxing transition between the Vasper session and the rest of your day. The cooling also aids in recovery from inflammation, pain, or soreness. Most Vasper users report no muscle soreness following their session. Vasper is designed to be a moderate, low-impact, non-damaging exercise session that still delivers the benefits of an intensive workout.');
INSERT INTO `wp_postmeta` VALUES (18930,912,'_summary_bullets_4_bullet_text','field_5dcc6cd55ed60');
