INSERT INTO `wp_postmeta` VALUES (19185,919,'tab_2_children_top_paragraph_3','Vasper training system to improve functional balance and decreased fall risk in independent  Living seniors: A QUALITY assurance report ');
INSERT INTO `wp_postmeta` VALUES (19186,919,'_tab_2_children_top_paragraph_3','field_5db8a77d6765e');
INSERT INTO `wp_postmeta` VALUES (19187,919,'tab_2_children','');
INSERT INTO `wp_postmeta` VALUES (19188,919,'_tab_2_children','field_5db8a77d67655');
INSERT INTO `wp_postmeta` VALUES (19189,919,'tab_name3','Rehabilitation Benefits');
INSERT INTO `wp_postmeta` VALUES (19190,919,'_tab_name3','field_5db87c98b729e');
INSERT INTO `wp_postmeta` VALUES (19191,919,'tab_3_paragraph','The rehabilitation process can be challenging, but it is possible. For those suffering from a concussion, Parkinson’s disease, or multiple sclerosis, Vasper has teamed up with leading research centers in order to unlock the potential of your treatment. Our Vasper research partners study the combined mobility benefits of our technology with aerobic & therapeutic exercise, to working with expert doctors to reduce the detrimental side effects a concussion may bring on, we are here to help all ability levels and health statuses. Together we do the research so you don’t have to.');
INSERT INTO `wp_postmeta` VALUES (19192,919,'_tab_3_paragraph','field_5db88712aed05');
INSERT INTO `wp_postmeta` VALUES (19193,919,'tab_3_image','300');
INSERT INTO `wp_postmeta` VALUES (19194,919,'_tab_3_image','field_5db884c842f6f');
INSERT INTO `wp_postmeta` VALUES (19195,919,'tab_3_children_tab_name_1','Concussions');
INSERT INTO `wp_postmeta` VALUES (19196,919,'_tab_3_children_tab_name_1','field_5db8a85f75b38');
INSERT INTO `wp_postmeta` VALUES (19197,919,'tab_3_children_top_paragraph_1','The Cantu Concussion Center at Emerson Hospital is one of the leading centers of concussion clinical treatment and research. Dr. Robert Cantu with Dr. Yi-Ning Wu designed a study to examine Vasper’s potential to help with concussion treatment.');
INSERT INTO `wp_postmeta` VALUES (19198,919,'_tab_3_children_top_paragraph_1','field_5db8a85f75b39');
INSERT INTO `wp_postmeta` VALUES (19199,919,'tab_3_children_tab_name_2','Parkinson\'s Disease');
INSERT INTO `wp_postmeta` VALUES (19200,919,'_tab_3_children_tab_name_2','field_5db8a85f75b3b');
INSERT INTO `wp_postmeta` VALUES (19201,919,'tab_3_children_top_paragraph_2','Aerobic exercise enabled with rehabilitation technology improves mobility and balance of patients with Parkinson’s disease: A quality assurance report');
