INSERT INTO `wp_postmeta` VALUES (19209,919,'tab_1_children_paragraph_title_1','Hormones are your body’s systemic signaling molecules and are released in different areas of the body and move through the circulatory system to regulate your body’s function and behavior. Hormones affect the body in many different ways and have significant impacts on function, form, and feel. ');
INSERT INTO `wp_postmeta` VALUES (19210,919,'_tab_1_children_paragraph_title_1','field_5db89bc1740f3');
INSERT INTO `wp_postmeta` VALUES (19211,919,'tab_1_children_paragraph_title_2','You’ve probably heard about stem cells in many different contexts. Stem cells are used in surgery, rehabilitation, medical devices, outpatient treatments, cosmetology, and dermatology.');
