INSERT INTO `wp_postmeta` VALUES (19213,919,'tab_1_children_paragraph_title_3','Vasper puts safety first. Before starting our clinical trial in cardiopulmonary rehabilitation, cardiologist Dr. Jeff Gladden wished to determine that Vasper does not cause a response that is different than conventional exercise.');
