INSERT INTO `wp_postmeta` VALUES (21898,991,'quote_block_2_photo','709');
INSERT INTO `wp_postmeta` VALUES (21899,991,'_quote_block_2_photo','field_5d8bdf4caaf49');
INSERT INTO `wp_postmeta` VALUES (21900,991,'quote_block_2_quote','Since offering Vasper therapy to my patients, I have seen incredible improvements in not only their health and disease, but in their motivation to continue to manage their health. It really has been a game changer for my patients with neurological disease. It is finally a highly effective treatment that does not have to be consumed, injected, or infused and does not come with toxicity concerns or adverse side effects. My patients with neurodegenerative disease have seen a slowing of progression, and patients with TBI and concussion have had improvement in their symptoms. Importantly, my patients with mitochondrial dysfunction have experienced significant improvements in their fatigue and muscle pain. In addition, the increased oxygen perfusion and improvement in neurotransmitter balance has greatly helped those with depression, pain, and anxiety. I am so happy to have the Vasper for my patients.');
INSERT INTO `wp_postmeta` VALUES (21901,991,'_quote_block_2_quote','field_5d8bdf27aaf47');
INSERT INTO `wp_postmeta` VALUES (21902,991,'quote_block_2_author','<strong>ILENE RUHOY</strong>\r\n<br/>MD, PHD CENTER FOR HEALING NEUROLOGY, SEATTLE, WA');
