INSERT INTO `wp_postmeta` VALUES (22154,1018,'_tab_1_children_tab_name_2','field_5db89ba9740f1');
INSERT INTO `wp_postmeta` VALUES (22155,1018,'tab_1_children_top_paragraph_2','You’ve probably heard about stem cells in many different contexts. Stem cells are used in surgery, rehabilitation, medical devices, outpatient treatments, cosmetology, and dermatology.');
INSERT INTO `wp_postmeta` VALUES (22156,1018,'_tab_1_children_top_paragraph_2','field_5db89beb740f6');
