INSERT INTO `wp_postmeta` VALUES (22159,1018,'tab_1_children_top_paragraph_3','Vasper puts safety first. Before starting our clinical trial in cardiopulmonary rehabilitation, cardiologist Dr. Jeff Gladden wished to determine that Vasper does not cause a response that is different than conventional exercise.');
