INSERT INTO `wp_postmeta` VALUES (22366,1022,'_tab_1','field_5e8ca6cb504a7');
INSERT INTO `wp_postmeta` VALUES (22367,1022,'tab_2_slide_intro_name','Lifestyle & Wellness Benefits');
INSERT INTO `wp_postmeta` VALUES (22368,1022,'_tab_2_slide_intro_name','field_5e8ca63579bc3');
INSERT INTO `wp_postmeta` VALUES (22369,1022,'tab_2_slide_intro_paragraph','At any age, you deserve to feel great – and that feeling should come easy. We’ve partnered with various individuals, from U.S. war veterans to independent living seniors, to understand the benefits of Vasper when it comes to sleep quality and emotional well-being. Using our non-invasive technology, our goal is to fully comprehend how individuals at any age or life experience can engage their body and achieve optimal energy levels &amp; wellness.');
INSERT INTO `wp_postmeta` VALUES (22370,1022,'_tab_2_slide_intro_paragraph','field_5e8ca60479bc2');
