INSERT INTO `wp_postmeta` VALUES (22566,295,'_tab_1_scientific_info_flex_0_scientific_block_content_1_image_for_mobile','field_5e8ce36d6a59b');
INSERT INTO `wp_postmeta` VALUES (22567,295,'tab_1_scientific_info_flex_1_scientific_title','Testosterone Increase');
INSERT INTO `wp_postmeta` VALUES (22568,295,'_tab_1_scientific_info_flex_1_scientific_title','field_5e8ce3c26a59d');
INSERT INTO `wp_postmeta` VALUES (22569,295,'tab_1_scientific_info_flex_1_scientific_block_content_0_scientific_text','And our hormone investigation didn’t stop there. Testosterone is a key hormone that is involved in regulating muscle growth, bone density, fat metabolism, and mood in both men and women. We explored this hormone with five professional baseball players in 8 Vasper sessions over 2 weeks. 80% saw an increase in free testosterone levels, with an average increase of 132% across all participants.');
INSERT INTO `wp_postmeta` VALUES (22570,295,'_tab_1_scientific_info_flex_1_scientific_block_content_0_scientific_text','field_5e8ce3ce6a5a0');
INSERT INTO `wp_postmeta` VALUES (22571,295,'tab_1_scientific_info_flex_1_scientific_block_content_0_image_for_desktop','1026');
INSERT INTO `wp_postmeta` VALUES (22572,295,'_tab_1_scientific_info_flex_1_scientific_block_content_0_image_for_desktop','field_5e8d01679f8e1');
INSERT INTO `wp_postmeta` VALUES (22573,295,'tab_1_scientific_info_flex_1_scientific_block_content_0_image_for_mobile','');
INSERT INTO `wp_postmeta` VALUES (22574,295,'_tab_1_scientific_info_flex_1_scientific_block_content_0_image_for_mobile','field_5e8d01539f8e0');
INSERT INTO `wp_postmeta` VALUES (22575,295,'tab_1_scientific_info_flex_1_scientific_block_content','1');
INSERT INTO `wp_postmeta` VALUES (22576,295,'_tab_1_scientific_info_flex_1_scientific_block_content','field_5e8ce3ce6a59f');
INSERT INTO `wp_postmeta` VALUES (22577,295,'tab_1_scientific_info_flex_2_background_image','1023');
INSERT INTO `wp_postmeta` VALUES (22578,295,'_tab_1_scientific_info_flex_2_background_image','field_5e8ce6646eeca');
INSERT INTO `wp_postmeta` VALUES (22579,295,'tab_1_scientific_info_flex_2_scientific_title','Safety Assessment');
INSERT INTO `wp_postmeta` VALUES (22580,295,'_tab_1_scientific_info_flex_2_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (22581,295,'tab_1_scientific_info_flex_2_scientific_block_content_0_scientific_text','In this study, we took 20 healthy participants to assess the safety of Vasper on the cardiovascular system. We compared heart rates and blood pressure values in 7 sessions with different leg pressures applied, ranging from <strong>0 mmHg</strong> to <strong>85 mmHg</strong>.');
INSERT INTO `wp_postmeta` VALUES (36381,1216,'hero_image','1017');
INSERT INTO `wp_postmeta` VALUES (22582,295,'_tab_1_scientific_info_flex_2_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
INSERT INTO `wp_postmeta` VALUES (22583,295,'tab_1_scientific_info_flex_2_scientific_block_content_0_image_for_desktop','1064');
INSERT INTO `wp_postmeta` VALUES (22584,295,'_tab_1_scientific_info_flex_2_scientific_block_content_0_image_for_desktop','field_5e8d00b3d162a');
INSERT INTO `wp_postmeta` VALUES (22585,295,'tab_1_scientific_info_flex_2_scientific_block_content_0_image_for_mobile','');
INSERT INTO `wp_postmeta` VALUES (22586,295,'_tab_1_scientific_info_flex_2_scientific_block_content_0_image_for_mobile','field_5e8ce36d6a59b');
INSERT INTO `wp_postmeta` VALUES (22587,295,'tab_1_scientific_info_flex_2_scientific_block_content_1_scientific_text','There was no significant difference in heart rate or blood pressure when comparing a session without Vasper’s cooling cuffs to a session with the cuffs at our allowed range of pressure (0-80mmHg). The study can be read in full here in the Journal of Exercise Physiology.');
INSERT INTO `wp_postmeta` VALUES (22588,295,'_tab_1_scientific_info_flex_2_scientific_block_content_1_scientific_text','field_5e8ce3326a59a');
