INSERT INTO `wp_postmeta` VALUES (22594,295,'_tab_1_scientific_info_flex_2_scientific_block_content','field_5e8ce38f6a59c');
INSERT INTO `wp_postmeta` VALUES (22595,1031,'hero_image','1017');
INSERT INTO `wp_postmeta` VALUES (22596,1031,'_hero_image','field_5db8697342399');
INSERT INTO `wp_postmeta` VALUES (22597,1031,'hero_title','The Research');
INSERT INTO `wp_postmeta` VALUES (22598,1031,'_hero_title','field_5db868eb4de19');
INSERT INTO `wp_postmeta` VALUES (22599,1031,'hero_paragraph','Vasper is a patented health technology designed to promote systemic health gains.\r\n\r\nOur mission is to provide non-invasive technology solutions that allow people to actively engage their body’s natural systems in achieving optimal health and wellness.\r\n\r\nTherefore we are dedicated to developing research studies that can help us understand how Vasper works and how it can affect people of all ages, ability levels and health statuses. We are have partnered with researchers and institutions around the world to examine hypotheses and produce rigorous scientific support for our theories. ');
INSERT INTO `wp_postmeta` VALUES (22600,1031,'_hero_paragraph','field_5db869004de1a');
INSERT INTO `wp_postmeta` VALUES (22601,1031,'tab_name1','');
INSERT INTO `wp_postmeta` VALUES (22602,1031,'_tab_name1','field_5db87c7eb729c');
INSERT INTO `wp_postmeta` VALUES (22603,1031,'tab_1_paragraph','');
INSERT INTO `wp_postmeta` VALUES (22604,1031,'_tab_1_paragraph','field_5db886deaed03');
INSERT INTO `wp_postmeta` VALUES (22605,1031,'tab_1_image','');
INSERT INTO `wp_postmeta` VALUES (22606,1031,'_tab_1_image','field_5db8849642f6d');
INSERT INTO `wp_postmeta` VALUES (22607,1031,'tab_1_children_tab_name_1','');
INSERT INTO `wp_postmeta` VALUES (22608,1031,'_tab_1_children_tab_name_1','field_5db89b89740ef');
INSERT INTO `wp_postmeta` VALUES (22609,1031,'tab_1_children_top_paragraph_1','Hormones are your body’s systemic signaling molecules and are released in different areas of the body and move through the circulatory system to regulate your body’s function and behavior. Hormones affect the body in many different ways and have significant impacts on function, form, and feel. ');
INSERT INTO `wp_postmeta` VALUES (22610,1031,'_tab_1_children_top_paragraph_1','field_5db89bc1740f3');
INSERT INTO `wp_postmeta` VALUES (22611,1031,'tab_1_children_tab_name_2','');
INSERT INTO `wp_postmeta` VALUES (22612,1031,'_tab_1_children_tab_name_2','field_5db89ba9740f1');
INSERT INTO `wp_postmeta` VALUES (22613,1031,'tab_1_children_top_paragraph_2','You’ve probably heard about stem cells in many different contexts. Stem cells are used in surgery, rehabilitation, medical devices, outpatient treatments, cosmetology, and dermatology.');
INSERT INTO `wp_postmeta` VALUES (22614,1031,'_tab_1_children_top_paragraph_2','field_5db89beb740f6');
INSERT INTO `wp_postmeta` VALUES (22615,1031,'tab_1_children_tab_name_3','');
INSERT INTO `wp_postmeta` VALUES (22616,1031,'_tab_1_children_tab_name_3','field_5db89bae740f2');
INSERT INTO `wp_postmeta` VALUES (22617,1031,'tab_1_children_top_paragraph_3','Vasper puts safety first. Before starting our clinical trial in cardiopulmonary rehabilitation, cardiologist Dr. Jeff Gladden wished to determine that Vasper does not cause a response that is different than conventional exercise.');
INSERT INTO `wp_postmeta` VALUES (22618,1031,'_tab_1_children_top_paragraph_3','field_5db89bf0740f7');
