INSERT INTO `wp_postmeta` VALUES (22723,1031,'tab_1_scientific_info_flex_0_scientific_title','Safety Assessment');
INSERT INTO `wp_postmeta` VALUES (22724,1031,'_tab_1_scientific_info_flex_0_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (22725,1031,'tab_1_scientific_info_flex_0_scientific_block_content_0_scientific_text','In this study, we compared heart rates and blood pressure values in 7 sessions with different leg pressures applied, ranging from <strong>0 mmHg</strong> to 85 <strong>mmHg</strong>.');
INSERT INTO `wp_postmeta` VALUES (22726,1031,'_tab_1_scientific_info_flex_0_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
INSERT INTO `wp_postmeta` VALUES (22727,1031,'tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_mobile','');
INSERT INTO `wp_postmeta` VALUES (22728,1031,'_tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_mobile','field_5e8ce36d6a59b');
INSERT INTO `wp_postmeta` VALUES (22729,1031,'tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','1024');
INSERT INTO `wp_postmeta` VALUES (22730,1031,'_tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','field_5e8d00b3d162a');
INSERT INTO `wp_postmeta` VALUES (22731,1031,'tab_1_scientific_info_flex_0_scientific_block_content','2');
INSERT INTO `wp_postmeta` VALUES (22732,1031,'_tab_1_scientific_info_flex_0_scientific_block_content','field_5e8ce38f6a59c');
INSERT INTO `wp_postmeta` VALUES (22733,1031,'tab_1_scientific_info_flex_0_scientific_block_content_1_scientific_text','There was no significant difference in heart rate or blood pressure when comparing a session without Vasper’s cooling cuffs to a session with the cuffs at our allowed range of pressure (0-80mmHg). The study can be read in full here in the Journal of Exercise Physiology.');
INSERT INTO `wp_postmeta` VALUES (22734,1031,'_tab_1_scientific_info_flex_0_scientific_block_content_1_scientific_text','field_5e8ce3326a59a');
INSERT INTO `wp_postmeta` VALUES (22735,1031,'tab_1_scientific_info_flex_0_scientific_block_content_1_image_for_desktop','');
INSERT INTO `wp_postmeta` VALUES (22736,1031,'_tab_1_scientific_info_flex_0_scientific_block_content_1_image_for_desktop','field_5e8d00b3d162a');
INSERT INTO `wp_postmeta` VALUES (22737,1031,'tab_1_scientific_info_flex_0_scientific_block_content_1_image_for_mobile','');
INSERT INTO `wp_postmeta` VALUES (22738,1031,'_tab_1_scientific_info_flex_0_scientific_block_content_1_image_for_mobile','field_5e8ce36d6a59b');
INSERT INTO `wp_postmeta` VALUES (22739,1031,'tab_1_scientific_info_flex_1_scientific_title','Testosterone Increase');
INSERT INTO `wp_postmeta` VALUES (22740,1031,'_tab_1_scientific_info_flex_1_scientific_title','field_5e8ce3c26a59d');
INSERT INTO `wp_postmeta` VALUES (22741,1031,'tab_1_scientific_info_flex_1_scientific_block_content_0_scientific_text','And our hormone investigation didn’t stop there. Testosterone is a key hormone that is involved in regulating muscle growth, bone density, fat metabolism, and mood in both men and women. We explored this hormone with five professional baseball players in 8 Vasper sessions over 2 weeks. 80% saw an increase in free testosterone levels, with an average increase of 132% across all participants.');
INSERT INTO `wp_postmeta` VALUES (22742,1031,'_tab_1_scientific_info_flex_1_scientific_block_content_0_scientific_text','field_5e8ce3ce6a5a0');
INSERT INTO `wp_postmeta` VALUES (22743,1031,'tab_1_scientific_info_flex_1_scientific_block_content_0_image_for_desktop','1026');
