INSERT INTO `wp_postmeta` VALUES (23062,1042,'_hero_image','field_5db8697342399');
INSERT INTO `wp_postmeta` VALUES (23063,1042,'hero_title','The Research');
INSERT INTO `wp_postmeta` VALUES (23064,1042,'_hero_title','field_5db868eb4de19');
INSERT INTO `wp_postmeta` VALUES (23065,1042,'hero_paragraph','Vasper is a patented health technology designed to promote systemic health gains.\r\n\r\nOur mission is to provide non-invasive technology solutions that allow people to actively engage their body’s natural systems in achieving optimal health and wellness.\r\n\r\nTherefore we are dedicated to developing research studies that can help us understand how Vasper works and how it can affect people of all ages, ability levels and health statuses. We are have partnered with researchers and institutions around the world to examine hypotheses and produce rigorous scientific support for our theories. ');
