INSERT INTO `wp_postmeta` VALUES (23250,1042,'_tab_3_scientific_info_flex_0_scientific_block_content','field_5e8ce38f6a59c');
INSERT INTO `wp_postmeta` VALUES (23251,1042,'tab_3_scientific_info_flex_1_scientific_title','Stem Cell Recruitment');
