INSERT INTO `wp_postmeta` VALUES (23699,1044,'tab_3_scientific_info_flex_1_scientific_title','Stem Cell Recruitment');
INSERT INTO `wp_postmeta` VALUES (23700,1044,'_tab_3_scientific_info_flex_1_scientific_title','field_5e8ce3c26a59d');
INSERT INTO `wp_postmeta` VALUES (23701,1044,'tab_3_scientific_info_flex_1_scientific_block_content_0_scientific_text','');
