INSERT INTO `wp_postmeta` VALUES (24179,1053,'tab_1_slide_intro_name','Physical Benefits');
INSERT INTO `wp_postmeta` VALUES (24180,1053,'_tab_1_slide_intro_name','field_5e8ca63579bc3');
INSERT INTO `wp_postmeta` VALUES (24181,1053,'tab_1_slide_intro_paragraph','To understand the physical benefits Vasper provides, we’ve conducted research, backed by supporting literature.\r\n\r\nIn order to study its impact effectively, Vasper conducted a safety study, which verifies Vasper is safe and easy to use for most.\r\n\r\nTime and time again, Vasper users talk about increases in energy and strength. In a small study, we observed significant increases in testosterone as a result of Vasper use. Though there may be other factors at play, it is likely this testosterone boost that explains the improvements in performance after Vasper use, which was discovered in a different study.\r\n\r\nCombined with its low impact physically and physiologically, the anabolic hormone increase with Vasper use is an unbeatable combination for anyone who wants to increase their physical performance.');
INSERT INTO `wp_postmeta` VALUES (24182,1053,'_tab_1_slide_intro_paragraph','field_5e8ca60479bc2');
