INSERT INTO `wp_postmeta` VALUES (24510,1054,'_tab_1_scientific_info_flex_0_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (24511,1054,'tab_1_scientific_info_flex_0_scientific_block_content_0_scientific_text','In this study, we compared heart rates and blood pressure values in 7 sessions with different leg pressures applied, ranging from <strong>0 mmHg</strong> to 85 <strong>mmHg</strong>.');
INSERT INTO `wp_postmeta` VALUES (24512,1054,'_tab_1_scientific_info_flex_0_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
INSERT INTO `wp_postmeta` VALUES (24513,1054,'tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_mobile','');
