INSERT INTO `wp_postmeta` VALUES (24515,1054,'tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','1024');
INSERT INTO `wp_postmeta` VALUES (24516,1054,'_tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','field_5e8d00b3d162a');
INSERT INTO `wp_postmeta` VALUES (24517,1054,'tab_1_scientific_info_flex_0_scientific_block_content','2');
INSERT INTO `wp_postmeta` VALUES (24518,1054,'_tab_1_scientific_info_flex_0_scientific_block_content','field_5e8ce38f6a59c');
INSERT INTO `wp_postmeta` VALUES (24519,1054,'tab_1_scientific_info_flex_0_scientific_block_content_1_scientific_text','There was no significant difference in heart rate or blood pressure when comparing a session without Vasper’s cooling cuffs to a session with the cuffs at our allowed range of pressure (0-80mmHg). The study can be read in full here in the Journal of Exercise Physiology.');
INSERT INTO `wp_postmeta` VALUES (24520,1054,'_tab_1_scientific_info_flex_0_scientific_block_content_1_scientific_text','field_5e8ce3326a59a');
