INSERT INTO `wp_postmeta` VALUES (25037,1056,'tab_1_slide_intro_name','Physical Benefits');
INSERT INTO `wp_postmeta` VALUES (25038,1056,'_tab_1_slide_intro_name','field_5e8ca63579bc3');
INSERT INTO `wp_postmeta` VALUES (25039,1056,'tab_1_slide_intro_paragraph','To understand the physical benefits Vasper provides, we’ve conducted research, backed by supporting literature.\r\n\r\nIn order to study its impact effectively, Vasper conducted a safety study, which verifies Vasper is safe and easy to use for most.\r\n\r\nTime and time again, Vasper users talk about increases in energy and strength. In a small study, we observed significant increases in testosterone as a result of Vasper use. Though there may be other factors at play, it is likely this testosterone boost that explains the improvements in performance after Vasper use, which was discovered in a different study.\r\n\r\nCombined with its low impact physically and physiologically, the anabolic hormone increase with Vasper use is an unbeatable combination for anyone who wants to increase their physical performance.');
INSERT INTO `wp_postmeta` VALUES (25040,1056,'_tab_1_slide_intro_paragraph','field_5e8ca60479bc2');
INSERT INTO `wp_postmeta` VALUES (25041,1056,'tab_1_slide_intro_image','298');
INSERT INTO `wp_postmeta` VALUES (25042,1056,'_tab_1_slide_intro_image','field_5e8ca5c579bc1');
INSERT INTO `wp_postmeta` VALUES (25043,1056,'tab_1_impact_message','Hormones are your body’s systemic signaling molecules and are released in different areas of the body and move through the circulatory system to regulate your body’s function and behavior. Hormones affect the body in many different ways and have significant impacts on function, form, and feel.');
INSERT INTO `wp_postmeta` VALUES (25044,1056,'_tab_1_impact_message','field_5e8ca64579bc4');
