INSERT INTO `wp_postmeta` VALUES (25128,1056,'_tab_3_scientific_info_flex_0_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (25129,1056,'tab_3_scientific_info_flex_0_scientific_block_content_0_scientific_text','ImPACT, BESS, King-Devick Test, SAC improved after the intervention in both groups but there was no significant difference between two groups.');
INSERT INTO `wp_postmeta` VALUES (25130,1056,'_tab_3_scientific_info_flex_0_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
INSERT INTO `wp_postmeta` VALUES (25131,1056,'tab_3_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','1033');
INSERT INTO `wp_postmeta` VALUES (25132,1056,'_tab_3_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','field_5e8d00b3d162a');
