INSERT INTO `wp_postmeta` VALUES (25700,1058,'_tab_3_scientific_info_flex_0_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (25701,1058,'tab_3_scientific_info_flex_0_scientific_block_content_0_scientific_text','ImPACT, BESS, King-Devick Test, SAC improved after the intervention in both groups but there was no significant difference between two groups.');
INSERT INTO `wp_postmeta` VALUES (25702,1058,'_tab_3_scientific_info_flex_0_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
INSERT INTO `wp_postmeta` VALUES (25703,1058,'tab_3_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','1033');
INSERT INTO `wp_postmeta` VALUES (25704,1058,'_tab_3_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','field_5e8d00b3d162a');
INSERT INTO `wp_postmeta` VALUES (25705,1058,'tab_3_scientific_info_flex_0_scientific_block_content_0_image_for_mobile','');
INSERT INTO `wp_postmeta` VALUES (25706,1058,'_tab_3_scientific_info_flex_0_scientific_block_content_0_image_for_mobile','field_5e8ce36d6a59b');
INSERT INTO `wp_postmeta` VALUES (25707,1058,'tab_3_scientific_info_flex_0_scientific_block_content_1_scientific_text','Changes of Quality of Life scores at two time points: right after 6-week intervention and at the follow-up. Significant continuous improvement is observed in the experimental group.\r\n\r\nThey were first interested in Vasper for concussions because of the cooling and the low-impact, moderate exertion protocols that were thought to reduce the detrimental side effects that concussion patients can have. The group focused on <strong>Post-Concussive Syndrome</strong>, patients which did not have their symptoms resolve after having a concussion and are typically considered difficult cases to manage.\r\n\r\nThe midpoint results of this study on Post-Concussive Syndrome rehabilitation shows that in 6 weeks of 2x Vasper sessions/week with physical therapy, the Vasper group showed statistically significant improvements over the control group, which just did physical therapy.\r\nNot only did the Vasper group demonstrate significantly improved quality of life at the end of the study, they also showed improvements in the follow-up period, when they weren’t doing Vasper or physical therapy for six weeks. The Vasper group had a significantly more stable recovery and specifically significant more stability in emotional and sleep contributions after 6 weeks of no rehabilitation. Symptom variability and stability of recovery is a particularly difficult issue in <strong>Post-Concussive Syndrome</strong> rehabilitation and this study demonstrates that Vasper is an effective way to address this.');
INSERT INTO `wp_postmeta` VALUES (25708,1058,'_tab_3_scientific_info_flex_0_scientific_block_content_1_scientific_text','field_5e8ce3326a59a');
INSERT INTO `wp_postmeta` VALUES (25709,1058,'tab_3_scientific_info_flex_0_scientific_block_content_1_image_for_desktop','');
