INSERT INTO `wp_postmeta` VALUES (25987,1059,'tab_3_scientific_info_flex_0_scientific_block_content_0_scientific_text','ImPACT, BESS, King-Devick Test, SAC improved after the intervention in both groups but there was no significant difference between two groups.');
INSERT INTO `wp_postmeta` VALUES (25988,1059,'_tab_3_scientific_info_flex_0_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
INSERT INTO `wp_postmeta` VALUES (25989,1059,'tab_3_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','1033');
