INSERT INTO `wp_postmeta` VALUES (26275,1060,'tab_3_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','1033');
INSERT INTO `wp_postmeta` VALUES (26276,1060,'_tab_3_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','field_5e8d00b3d162a');
