INSERT INTO `wp_postmeta` VALUES (26923,1062,'tab_2_scientific_info_flex_2_scientific_title','Hormonal Response: Growth Hormone, Cortisol, and Testosterone');
INSERT INTO `wp_postmeta` VALUES (26924,1062,'_tab_2_scientific_info_flex_2_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (26925,1062,'tab_2_scientific_info_flex_2_scientific_block_content_0_scientific_text','');
