INSERT INTO `wp_postmeta` VALUES (27052,1063,'_tab_1','field_5e8ca6cb504a7');
INSERT INTO `wp_postmeta` VALUES (27053,1063,'tab_2_slide_intro_name','Lifestyle & Wellness Benefits');
INSERT INTO `wp_postmeta` VALUES (27054,1063,'_tab_2_slide_intro_name','field_5e8ca63579bc3');
INSERT INTO `wp_postmeta` VALUES (27055,1063,'tab_2_slide_intro_paragraph','At any age, you deserve to feel great — and that feeling should come easy. We’ve partnered with various individuals, from US war veterans to independent living seniors, to understand the benefits of Vasper when it comes to sleep and emotional well-being. Our <a href=\"#safety-assessments\">safety study</a> has assured us that any person ranging in age and physical ability can use our system. Using our non-invasive technology, our goal is to fully comprehend how individuals at any age or life experience can engage their body to achieve optimal energy levels &amp; wellness. Some of our strongest evidence suggests that Vasper can <a href=\"#improved-sleep-quality\">improve sleep quality</a>. Though there may be many explanations for this, we have found that Vasper <a href=\"#hormonal-response:-growth-hormone,-cortisol,-and-testosterone\">decreases stress levels</a> specifically at night.');
INSERT INTO `wp_postmeta` VALUES (27056,1063,'_tab_2_slide_intro_paragraph','field_5e8ca60479bc2');
