INSERT INTO `wp_postmeta` VALUES (27498,1065,'_tab_2_scientific_info_flex_2_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (27499,1065,'tab_2_scientific_info_flex_2_scientific_block_content_0_scientific_text','');
