INSERT INTO `wp_postmeta` VALUES (27666,1066,'_tab_1_scientific_info_flex_0_scientific_block_content','field_5e8ce38f6a59c');
INSERT INTO `wp_postmeta` VALUES (27667,1066,'tab_1_scientific_info_flex_0_scientific_block_content_1_scientific_text','There was no significant difference in heart rate or blood pressure when comparing a session without Vasper’s cooling cuffs to a session with the cuffs at our allowed range of pressure (0-80mmHg). The study can be read in full here in the Journal of Exercise Physiology.');
