INSERT INTO `wp_postmeta` VALUES (28235,1068,'tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','1064');
INSERT INTO `wp_postmeta` VALUES (28236,1068,'_tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','field_5e8d00b3d162a');
INSERT INTO `wp_postmeta` VALUES (28237,1068,'tab_1_scientific_info_flex_0_scientific_block_content','2');
INSERT INTO `wp_postmeta` VALUES (28238,1068,'_tab_1_scientific_info_flex_0_scientific_block_content','field_5e8ce38f6a59c');
INSERT INTO `wp_postmeta` VALUES (28239,1068,'tab_1_scientific_info_flex_0_scientific_block_content_1_scientific_text','There was no significant difference in heart rate or blood pressure when comparing a session without Vasper’s cooling cuffs to a session with the cuffs at our allowed range of pressure (0-80mmHg). The study can be read in full here in the Journal of Exercise Physiology.');
INSERT INTO `wp_postmeta` VALUES (28240,1068,'_tab_1_scientific_info_flex_0_scientific_block_content_1_scientific_text','field_5e8ce3326a59a');
