INSERT INTO `wp_postmeta` VALUES (28477,1069,'tab_1_impact_message','Hormones are your body’s systemic signaling molecules and are released in different areas of the body and move through the circulatory system to regulate your body’s function and behavior. Hormones affect the body in many different ways and have significant impacts on function, form, and feel.');
