INSERT INTO `wp_postmeta` VALUES (28521,1069,'tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','1064');
INSERT INTO `wp_postmeta` VALUES (28522,1069,'_tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','field_5e8d00b3d162a');
