INSERT INTO `wp_postmeta` VALUES (28803,1071,'tab_1_scientific_info_flex_0_scientific_title','Safety Assessment');
INSERT INTO `wp_postmeta` VALUES (28804,1071,'_tab_1_scientific_info_flex_0_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (28805,1071,'tab_1_scientific_info_flex_0_scientific_block_content_0_scientific_text','In this study, we compared heart rates and blood pressure values in 7 sessions with different leg pressures applied, ranging from <strong>0 mmHg</strong> to <strong>85 mmHg</strong>.');
INSERT INTO `wp_postmeta` VALUES (28806,1071,'_tab_1_scientific_info_flex_0_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
INSERT INTO `wp_postmeta` VALUES (28807,1071,'tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_mobile','');
INSERT INTO `wp_postmeta` VALUES (28808,1071,'_tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_mobile','field_5e8ce36d6a59b');
INSERT INTO `wp_postmeta` VALUES (28809,1071,'tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','1064');
INSERT INTO `wp_postmeta` VALUES (28810,1071,'_tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','field_5e8d00b3d162a');
INSERT INTO `wp_postmeta` VALUES (28811,1071,'tab_1_scientific_info_flex_0_scientific_block_content','2');
INSERT INTO `wp_postmeta` VALUES (28812,1071,'_tab_1_scientific_info_flex_0_scientific_block_content','field_5e8ce38f6a59c');
INSERT INTO `wp_postmeta` VALUES (28813,1071,'tab_1_scientific_info_flex_0_scientific_block_content_1_scientific_text','There was no significant difference in heart rate or blood pressure when comparing a session without Vasper’s cooling cuffs to a session with the cuffs at our allowed range of pressure (0-80mmHg). The study can be read in full here in the Journal of Exercise Physiology.');
INSERT INTO `wp_postmeta` VALUES (28814,1071,'_tab_1_scientific_info_flex_0_scientific_block_content_1_scientific_text','field_5e8ce3326a59a');
INSERT INTO `wp_postmeta` VALUES (28815,1071,'tab_1_scientific_info_flex_0_scientific_block_content_1_image_for_desktop','');
INSERT INTO `wp_postmeta` VALUES (28816,1071,'_tab_1_scientific_info_flex_0_scientific_block_content_1_image_for_desktop','field_5e8d00b3d162a');
INSERT INTO `wp_postmeta` VALUES (28817,1071,'tab_1_scientific_info_flex_0_scientific_block_content_1_image_for_mobile','');
INSERT INTO `wp_postmeta` VALUES (28818,1071,'_tab_1_scientific_info_flex_0_scientific_block_content_1_image_for_mobile','field_5e8ce36d6a59b');
INSERT INTO `wp_postmeta` VALUES (28819,1071,'tab_1_scientific_info_flex_1_scientific_title','Testosterone Increase');
INSERT INTO `wp_postmeta` VALUES (28820,1071,'_tab_1_scientific_info_flex_1_scientific_title','field_5e8ce3c26a59d');
INSERT INTO `wp_postmeta` VALUES (28821,1071,'tab_1_scientific_info_flex_1_scientific_block_content_0_scientific_text','And our hormone investigation didn’t stop there. Testosterone is a key hormone that is involved in regulating muscle growth, bone density, fat metabolism, and mood in both men and women. We explored this hormone with five professional baseball players in 8 Vasper sessions over 2 weeks. 80% saw an increase in free testosterone levels, with an average increase of 132% across all participants.');
