INSERT INTO `wp_postmeta` VALUES (29936,1078,'_tab_2','field_5e8ce72c94c28');
INSERT INTO `wp_postmeta` VALUES (29937,1078,'tab_3_slide_intro_name','Rehabilitation Benefits');
INSERT INTO `wp_postmeta` VALUES (29938,1078,'_tab_3_slide_intro_name','field_5e8ca63579bc3');
INSERT INTO `wp_postmeta` VALUES (29939,1078,'tab_3_slide_intro_paragraph','The health benefits from Vasper are numerous and broad. Our work with a wide spectrum of clients has taught us that our system can be used to alleviate symptoms and provide support for a number of diseases and conditions. We’ve partnered with top hospitals and clinics to investigate the potential benefits of Vasper use in different clinical settings. Though the specific mechanisms for how Vasper helps in the body are still being investigated, many of our studies have shown that Vasper can help with a multitude of illnesses and conditions. A randomized control trial found that Vasper <a href=\"#neurological-benefits\">helps neurologically</a>. One possible reason we see improvements in the nervous and musculoskeletal systems is the <a href=\"#stem-cell-recruitment\">activation of stem cells</a> in the body after a Vasper session. Lastly, our work with Veterans has taught us that Vasper can help manage trauma-related stress, <a href=\"#emotional-and-energy-improvement\">increase sleep quality</a>, and <a href=\"#emotional-and-energy-improvement\">improve emotional wellbeing and energy levels</a>.');
INSERT INTO `wp_postmeta` VALUES (29940,1078,'_tab_3_slide_intro_paragraph','field_5e8ca60479bc2');
