INSERT INTO `wp_postmeta` VALUES (31960,1115,'_tab_1_scientific_info_flex_1_scientific_block_content','field_5e8ce3ce6a59f');
INSERT INTO `wp_postmeta` VALUES (31961,1115,'tab_1_scientific_info_flex_2_background_image','1027');
INSERT INTO `wp_postmeta` VALUES (31962,1115,'_tab_1_scientific_info_flex_2_background_image','field_5e8ce6646eeca');
INSERT INTO `wp_postmeta` VALUES (31963,1115,'tab_1_scientific_info_flex_2_scientific_title','Performance Increase');
INSERT INTO `wp_postmeta` VALUES (31964,1115,'_tab_1_scientific_info_flex_2_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (31965,1115,'tab_1_scientific_info_flex_2_scientific_block_content_0_scientific_text','But what does all this talk about hormone levels mean? Let’s take a look at the real-life impact of changing hormone levels. Vasper worked with San Jose Sharks Strength and Conditioning Coach Mike Potenza to work with the 131st ParaRescue Squadron to assess hormone levels and performance results. ParaRescuemen are elite military operators, who specialize in medical rescue in war zones and remote areas. Due to the stress and length of their deployments, higher cortisol levels, sleep disturbances, and the resulting effects on their performance were a top concern.');
INSERT INTO `wp_postmeta` VALUES (31966,1115,'_tab_1_scientific_info_flex_2_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
