INSERT INTO `wp_postmeta` VALUES (32564,1127,'summary_title','What You Need <br class=\"mobile-only\"/>to Know');
INSERT INTO `wp_postmeta` VALUES (32565,1127,'_summary_title','field_5dcc6bf0b1cdc');
INSERT INTO `wp_postmeta` VALUES (32566,1127,'summary_bullets_0_bullet_image','408');
INSERT INTO `wp_postmeta` VALUES (32567,1127,'_summary_bullets_0_bullet_image','field_5dcc6cb55ed5e');
INSERT INTO `wp_postmeta` VALUES (32568,1127,'summary_bullets_0_bullet_title','Physical');
INSERT INTO `wp_postmeta` VALUES (32569,1127,'_summary_bullets_0_bullet_title','field_5dcc6cc25ed5f');
INSERT INTO `wp_postmeta` VALUES (32570,1127,'summary_bullets_0_bullet_text','Vasper is based on three scientifically proven principles – compression technology, cooling and interval training. When all principles are working together, the results are extraordinary. Compression and cooling create the effect of high intensity (anaerobic) exercise without the time, effort, and muscle damage it takes to achieve the same results with conventional exercise.');
INSERT INTO `wp_postmeta` VALUES (32571,1127,'_summary_bullets_0_bullet_text','field_5dcc6cd55ed60');
INSERT INTO `wp_postmeta` VALUES (32572,1127,'summary_bullets_1_bullet_image','409');
INSERT INTO `wp_postmeta` VALUES (32573,1127,'_summary_bullets_1_bullet_image','field_5dcc6cb55ed5e');
INSERT INTO `wp_postmeta` VALUES (32574,1127,'summary_bullets_1_bullet_title','Attire');
INSERT INTO `wp_postmeta` VALUES (32575,1127,'_summary_bullets_1_bullet_title','field_5dcc6cc25ed5f');
INSERT INTO `wp_postmeta` VALUES (32576,1127,'summary_bullets_1_bullet_text','Normal exercise attire is fine! We recommend a shirt with sleeves and shorts, as well as avoiding exercise tights that are too compressive or slick. The workout is performed barefoot so there is no need to have athletic footwear.');
INSERT INTO `wp_postmeta` VALUES (32577,1127,'_summary_bullets_1_bullet_text','field_5dcc6cd55ed60');
INSERT INTO `wp_postmeta` VALUES (32578,1127,'summary_bullets_2_bullet_image','410');
INSERT INTO `wp_postmeta` VALUES (32579,1127,'_summary_bullets_2_bullet_image','field_5dcc6cb55ed5e');
INSERT INTO `wp_postmeta` VALUES (32580,1127,'summary_bullets_2_bullet_title','Shoes');
INSERT INTO `wp_postmeta` VALUES (32581,1127,'_summary_bullets_2_bullet_title','field_5dcc6cc25ed5f');
INSERT INTO `wp_postmeta` VALUES (32582,1127,'summary_bullets_2_bullet_text','No shoes needed! You are barefoot during your Vasper session because we are cooling your feet! The bottom of your feet is one of the most effective areas of the body for heat exchange, so by cooling the soles of your feet, the heat generated by your body is released, which helps you stay comfortably cool and minimize sweating.');
INSERT INTO `wp_postmeta` VALUES (32583,1127,'_summary_bullets_2_bullet_text','field_5dcc6cd55ed60');
INSERT INTO `wp_postmeta` VALUES (32584,1127,'summary_bullets_3_bullet_image','411');
INSERT INTO `wp_postmeta` VALUES (32585,1127,'_summary_bullets_3_bullet_image','field_5dcc6cb55ed5e');
INSERT INTO `wp_postmeta` VALUES (32586,1127,'summary_bullets_3_bullet_title','Time');
INSERT INTO `wp_postmeta` VALUES (32587,1127,'_summary_bullets_3_bullet_title','field_5dcc6cc25ed5f');
INSERT INTO `wp_postmeta` VALUES (32588,1127,'summary_bullets_3_bullet_text','Vasper focused on 21-minute sessions, in which you will complete a low-impact high-intensity workout. Replacing all the work that you would normally do in longer workouts with other programs you can get in a customizable program with Vasper’s NuStep T5XR platform. Vasper leaves you energized and rejuvenated, alleviating your body aches and pains.');
INSERT INTO `wp_postmeta` VALUES (32589,1127,'_summary_bullets_3_bullet_text','field_5dcc6cd55ed60');
INSERT INTO `wp_postmeta` VALUES (32590,1127,'summary_bullets_4_bullet_image','412');
INSERT INTO `wp_postmeta` VALUES (32591,1127,'_summary_bullets_4_bullet_image','field_5dcc6cb55ed5e');
INSERT INTO `wp_postmeta` VALUES (32592,1127,'summary_bullets_4_bullet_title','End of Session');
INSERT INTO `wp_postmeta` VALUES (32593,1127,'_summary_bullets_4_bullet_title','field_5dcc6cc25ed5f');
INSERT INTO `wp_postmeta` VALUES (32594,1127,'summary_bullets_4_bullet_text','After your Vasper session, you will lay on a cooling pad for 5-15 minutes. This time allows your heart rate and breathing to return to your resting rates and acts as a relaxing transition between the Vasper session and the rest of your day. The cooling also aids in recovery from inflammation, pain, or soreness. Most Vasper users report no muscle soreness following their session. Vasper is designed to be a moderate, low-impact, non-damaging exercise session that still delivers the benefits of an intensive workout.');
INSERT INTO `wp_postmeta` VALUES (32595,1127,'_summary_bullets_4_bullet_text','field_5dcc6cd55ed60');
INSERT INTO `wp_postmeta` VALUES (32596,1127,'summary_bullets_5_bullet_image','413');
INSERT INTO `wp_postmeta` VALUES (32597,1127,'_summary_bullets_5_bullet_image','field_5dcc6cb55ed5e');
INSERT INTO `wp_postmeta` VALUES (32598,1127,'summary_bullets_5_bullet_title','Keep Hydrated');
INSERT INTO `wp_postmeta` VALUES (32599,1127,'_summary_bullets_5_bullet_title','field_5dcc6cc25ed5f');
INSERT INTO `wp_postmeta` VALUES (32600,1127,'summary_bullets_5_bullet_text','Just like any other workout, it is important to stay hydrated before, during, and after your Vasper workout. Your body is going through growth and recovery, through the form of a low-impact high-intensity workout. Water is essential for top performance and recovery.');
INSERT INTO `wp_postmeta` VALUES (32601,1127,'_summary_bullets_5_bullet_text','field_5dcc6cd55ed60');
