INSERT INTO `wp_postmeta` VALUES (33809,1174,'quote_block_1_author','<strong>DARRYL KAN</strong>\r\n<br/>MD ORTHOPEDIC SURGEON, QUEENS MEDICAL CENTER HAWAII, FORMER NFL QUARTERBACK');
