INSERT INTO `wp_postmeta` VALUES (35653,1209,'tab_1_scientific_info_flex_0_scientific_block_content','2');
INSERT INTO `wp_postmeta` VALUES (35654,1209,'_tab_1_scientific_info_flex_0_scientific_block_content','field_5e8ce38f6a59c');
INSERT INTO `wp_postmeta` VALUES (35655,1209,'tab_1_scientific_info_flex_0_scientific_block_content_1_scientific_text','There was no significant difference in heart rate or blood pressure when comparing a session without Vasper’s cooling cuffs to a session with the cuffs at our allowed range of pressure (0-80mmHg). The study can be read in full here in the Journal of Exercise Physiology.');
INSERT INTO `wp_postmeta` VALUES (35656,1209,'_tab_1_scientific_info_flex_0_scientific_block_content_1_scientific_text','field_5e8ce3326a59a');
