INSERT INTO `wp_postmeta` VALUES (35688,1209,'_tab_1_scientific_info_flex_2_scientific_block_content','field_5e8ce38f6a59c');
INSERT INTO `wp_postmeta` VALUES (35689,1209,'tab_3_scientific_info_flex_0_background_image','1032');
