INSERT INTO `wp_postmeta` VALUES (35933,1210,'tab_1_scientific_info_flex_0_scientific_block_content_0_scientific_text','In this study, we compared heart rates and blood pressure values in 7 sessions with different leg pressures applied, ranging from <strong>0 mmHg</strong> to <strong>85 mmHg</strong>.');
