INSERT INTO `wp_postmeta` VALUES (36189,1215,'tab_1_scientific_info_flex','a:3:{i:0;s:27:\"block_with_background_image\";i:1;s:26:\"block_with_blue_background\";i:2;s:27:\"block_with_background_image\";}');
INSERT INTO `wp_postmeta` VALUES (36190,1215,'_tab_1_scientific_info_flex','field_5e8ca67a79bc6');
INSERT INTO `wp_postmeta` VALUES (36191,1215,'tab_1','');
INSERT INTO `wp_postmeta` VALUES (36192,1215,'_tab_1','field_5e8ca6cb504a7');
INSERT INTO `wp_postmeta` VALUES (36193,1215,'tab_2_slide_intro_name','Health');
INSERT INTO `wp_postmeta` VALUES (36194,1215,'_tab_2_slide_intro_name','field_5e8ca63579bc3');
INSERT INTO `wp_postmeta` VALUES (36195,1215,'tab_2_slide_intro_paragraph','At any age, you deserve to feel great — and that feeling should come easy. We’ve partnered with various individuals, from US war veterans to independent living seniors, to understand the benefits of Vasper when it comes to sleep and emotional well-being. Our <a href=\"#safety-assessments\">safety study</a> has assured us that any person ranging in age and physical ability can use our system. Using our non-invasive technology, our goal is to fully comprehend how individuals at any age or life experience can engage their body to achieve optimal energy levels &amp; wellness. Some of our strongest evidence suggests that Vasper can <a href=\"#improved-sleep-quality\">improve sleep quality</a>. Though there may be many explanations for this, we have found that Vasper <a href=\"#hormonal-response:-growth-hormone,-cortisol,-and-testosterone\">decreases stress levels</a> specifically at night.');
INSERT INTO `wp_postmeta` VALUES (36196,1215,'_tab_2_slide_intro_paragraph','field_5e8ca60479bc2');
INSERT INTO `wp_postmeta` VALUES (36197,1215,'tab_2_slide_intro_image','299');
INSERT INTO `wp_postmeta` VALUES (36198,1215,'_tab_2_slide_intro_image','field_5e8ca5c579bc1');
INSERT INTO `wp_postmeta` VALUES (36199,1215,'tab_2_impact_message','Sleep is the most important biological currency in our body. Receiving quality sleep can improve mood, weight, and even immune function.');
INSERT INTO `wp_postmeta` VALUES (36200,1215,'_tab_2_impact_message','field_5e8ca64579bc4');
INSERT INTO `wp_postmeta` VALUES (36201,1215,'tab_2_impact_background_image','1020');
INSERT INTO `wp_postmeta` VALUES (36202,1215,'_tab_2_impact_background_image','field_5e8ca66d79bc5');
INSERT INTO `wp_postmeta` VALUES (36203,1215,'tab_2_scientific_info_flex','a:4:{i:0;s:27:\"block_with_background_image\";i:1;s:26:\"block_with_blue_background\";i:2;s:27:\"block_with_background_image\";i:3;s:26:\"block_with_blue_background\";}');
INSERT INTO `wp_postmeta` VALUES (36204,1215,'_tab_2_scientific_info_flex','field_5e8ca67a79bc6');
INSERT INTO `wp_postmeta` VALUES (36205,1215,'tab_2','');
INSERT INTO `wp_postmeta` VALUES (36206,1215,'_tab_2','field_5e8ce72c94c28');
INSERT INTO `wp_postmeta` VALUES (36207,1215,'tab_3_slide_intro_name','Rehabilitation');
INSERT INTO `wp_postmeta` VALUES (36208,1215,'_tab_3_slide_intro_name','field_5e8ca63579bc3');
INSERT INTO `wp_postmeta` VALUES (36209,1215,'tab_3_slide_intro_paragraph','The health benefits from Vasper are numerous and broad. Our work with a wide spectrum of clients has taught us that our system can be used to alleviate symptoms and provide support for a number of diseases and conditions. We’ve partnered with top hospitals and clinics to investigate the potential benefits of Vasper use in different clinical settings. Though the specific mechanisms for how Vasper helps in the body are still being investigated, many of our studies have shown that Vasper can help with a multitude of illnesses and conditions. A randomized control trial found that Vasper <a href=\"#neurological-benefits\">helps neurologically</a>. One possible reason we see improvements in the nervous and musculoskeletal systems is the <a href=\"#stem-cell-recruitment\">activation of stem cells</a> in the body after a Vasper session. Lastly, our work with Veterans has taught us that Vasper can help manage trauma-related stress, <a href=\"#emotional-and-energy-improvement\">increase sleep quality</a>, and <a href=\"#emotional-and-energy-improvement\">improve emotional wellbeing and energy levels</a>.');
INSERT INTO `wp_postmeta` VALUES (36210,1215,'_tab_3_slide_intro_paragraph','field_5e8ca60479bc2');
INSERT INTO `wp_postmeta` VALUES (36211,1215,'tab_3_slide_intro_image','300');
INSERT INTO `wp_postmeta` VALUES (36212,1215,'_tab_3_slide_intro_image','field_5e8ca5c579bc1');
INSERT INTO `wp_postmeta` VALUES (36213,1215,'tab_3_impact_message','Stem cells are specialized human cells with the ability to transform to many cell types from muscle cells to brain cells. Their amazing potential for healing has made them popular in mainstream and medical media.');
INSERT INTO `wp_postmeta` VALUES (36214,1215,'_tab_3_impact_message','field_5e8ca64579bc4');
INSERT INTO `wp_postmeta` VALUES (36215,1215,'tab_3_impact_background_image','1021');
