INSERT INTO `wp_postmeta` VALUES (36223,1215,'tab_1_scientific_info_flex_0_scientific_title','Safety Assessment');
INSERT INTO `wp_postmeta` VALUES (36224,1215,'_tab_1_scientific_info_flex_0_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (36225,1215,'tab_1_scientific_info_flex_0_scientific_block_content_0_scientific_text','In this study, we compared heart rates and blood pressure values in 7 sessions with different leg pressures applied, ranging from <strong>0 mmHg</strong> to <strong>85 mmHg</strong>.');
