INSERT INTO `wp_postmeta` VALUES (36229,1215,'tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','1064');
INSERT INTO `wp_postmeta` VALUES (36230,1215,'_tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','field_5e8d00b3d162a');
