INSERT INTO `wp_postmeta` VALUES (36552,1216,'_tab_1_scientific_info_flex_2_scientific_block_content','field_5e8ce38f6a59c');
INSERT INTO `wp_postmeta` VALUES (36553,1216,'tab_3_scientific_info_flex_0_background_image','1032');
