INSERT INTO `wp_postmeta` VALUES (37111,1218,'tab_1_scientific_info_flex_2_scientific_block_content_0_scientific_text','In this study, we compared heart rates and blood pressure values in 7 sessions with different leg pressures applied, ranging from <strong>0 mmHg</strong> to <strong>85 mmHg</strong>.');
