INSERT INTO `wp_postmeta` VALUES (37368,1219,'_tab_1_scientific_info_flex_0_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (37369,1219,'tab_1_scientific_info_flex_0_scientific_block_content_0_scientific_text','Vasper worked with San Jose Sharks Strength and Conditioning Coach Mike Potenza to work with the 131st ParaRescue Squadron to assess hormone levels and performance results. ParaRescuemen are elite military operators, who specialize in medical rescue in war zones and remote areas. Due to the stress and length of their deployments, higher cortisol levels, sleep disturbances, and the resulting effects on their performance were a top concern.\r\n\r\n\r\nVasper Pararescue trial: Performance results\r\nThe difference didn’t just show in their hormones - the Vasper group performed better on typical military performance tests, such as:');
INSERT INTO `wp_postmeta` VALUES (37370,1219,'_tab_1_scientific_info_flex_0_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
