INSERT INTO `wp_postmeta` VALUES (40280,1231,'_tab_2_scientific_info_flex','field_5e8ca67a79bc6');
INSERT INTO `wp_postmeta` VALUES (40281,1231,'tab_2','');
INSERT INTO `wp_postmeta` VALUES (40282,1231,'_tab_2','field_5e8ce72c94c28');
INSERT INTO `wp_postmeta` VALUES (40283,1231,'tab_3_slide_intro_name','Rehabilitation');
INSERT INTO `wp_postmeta` VALUES (40284,1231,'_tab_3_slide_intro_name','field_5e8ca63579bc3');
INSERT INTO `wp_postmeta` VALUES (40285,1231,'tab_3_slide_intro_paragraph','The health benefits from Vasper are numerous and broad. Our work with a wide spectrum of clients has taught us that our system can be used to alleviate symptoms and provide support for a number of diseases and conditions. We’ve partnered with top hospitals and clinics to investigate the potential benefits of Vasper use in different clinical settings. Though the specific mechanisms for how Vasper helps in the body are still being investigated, many of our studies have shown that Vasper can help with a multitude of illnesses and conditions. A randomized control trial found that Vasper <a href=\"#neurological-benefits\">helps neurologically</a>. One possible reason we see improvements in the nervous and musculoskeletal systems is the <a href=\"#stem-cell-recruitment\">activation of stem cells</a> in the body after a Vasper session. Lastly, our work with Veterans has taught us that Vasper can help manage trauma-related stress, <a href=\"#emotional-and-energy-improvement\">increase sleep quality</a>, and <a href=\"#emotional-and-energy-improvement\">improve emotional wellbeing and energy levels</a>.');
INSERT INTO `wp_postmeta` VALUES (40286,1231,'_tab_3_slide_intro_paragraph','field_5e8ca60479bc2');
INSERT INTO `wp_postmeta` VALUES (40287,1231,'tab_3_slide_intro_image','300');
INSERT INTO `wp_postmeta` VALUES (40288,1231,'_tab_3_slide_intro_image','field_5e8ca5c579bc1');
INSERT INTO `wp_postmeta` VALUES (40289,1231,'tab_3_impact_message','Stem cells are specialized human cells with the ability to transform to many cell types from muscle cells to brain cells. Their amazing potential for healing has made them popular in mainstream and medical media.');
INSERT INTO `wp_postmeta` VALUES (40290,1231,'_tab_3_impact_message','field_5e8ca64579bc4');
