INSERT INTO `wp_postmeta` VALUES (41644,1235,'_tab_3_scientific_info_flex_1_scientific_block_content_0_image_for_mobile','field_5e8d01539f8e0');
INSERT INTO `wp_postmeta` VALUES (41645,1235,'tab_3_scientific_info_flex_1_scientific_block_content_1_scientific_text','This study demonstrated that HSC can be significantly increased immediately after a Vasper session, and a significant <strong>increase of lympohocytes</strong> plus the <strong>decrease of neutrophils</strong> represents a favorable interaction of the body’s ability to prepare for resolution of muscle injury.\r\n\r\n<strong>Jagiellonian University</strong>, a top research university in Krakow, Poland, saw the above results and thought there might be applications\r\nin cardiology. <strong>Dr. Mikolaj Maga</strong> is leading a study that looks at how your stem cells and blood vessels respond to exercise with Vasper.\r\nJust as stem cells can help regrow cartilage, they also help repair vessels and veins (the endothelium), a process called <strong>angiogenesis</strong>.');
INSERT INTO `wp_postmeta` VALUES (41646,1235,'_tab_3_scientific_info_flex_1_scientific_block_content_1_scientific_text','field_5e8ce3ce6a5a0');
