INSERT INTO `wp_postmeta` VALUES (42577,1238,'tab_1_scientific_info_flex_2_scientific_block_content_1_scientific_text','There was no significant difference in heart rate or blood pressure when comparing a session without Vasper’s cooling cuffs to a session <span class=\"d-lg-none\"> </span><span class=\"d-inline d-lg-block\">with the cuffs at our allowed range of pressure (0-80mmHg). The study can be read in full here in the Journal of Exercise Physiology.</span>');
