INSERT INTO `wp_postmeta` VALUES (42843,1239,'tab_2_scientific_info_flex','a:4:{i:0;s:27:\"block_with_background_image\";i:1;s:26:\"block_with_blue_background\";i:2;s:27:\"block_with_background_image\";i:3;s:26:\"block_with_blue_background\";}');
INSERT INTO `wp_postmeta` VALUES (42844,1239,'_tab_2_scientific_info_flex','field_5e8ca67a79bc6');
INSERT INTO `wp_postmeta` VALUES (42845,1239,'tab_2','');
INSERT INTO `wp_postmeta` VALUES (42846,1239,'_tab_2','field_5e8ce72c94c28');
INSERT INTO `wp_postmeta` VALUES (42847,1239,'tab_3_slide_intro_name','Rehabilitation');
INSERT INTO `wp_postmeta` VALUES (42848,1239,'_tab_3_slide_intro_name','field_5e8ca63579bc3');
INSERT INTO `wp_postmeta` VALUES (42849,1239,'tab_3_slide_intro_paragraph','The health benefits from Vasper are numerous and broad. Our work with a wide spectrum of clients has taught us that our system can be used to alleviate symptoms and provide support for a number of diseases and conditions. We’ve partnered with top hospitals and clinics to investigate the potential benefits of Vasper use in different clinical settings. Though the specific mechanisms for how Vasper helps in the body are still being investigated, many of our studies have shown that Vasper can help with a multitude of illnesses and conditions. A randomized control trial found that Vasper <a href=\"#neurological-benefits\">helps neurologically</a>. One possible reason we see improvements in the nervous and musculoskeletal systems is the <a href=\"#stem-cell-recruitment\">activation of stem cells</a> in the body after a Vasper session. Lastly, our work with Veterans has taught us that Vasper can help manage trauma-related stress, <a href=\"#emotional-and-energy-improvement\">increase sleep quality</a>, and <a href=\"#emotional-and-energy-improvement\">improve emotional wellbeing and energy levels</a>.');
INSERT INTO `wp_postmeta` VALUES (42850,1239,'_tab_3_slide_intro_paragraph','field_5e8ca60479bc2');
INSERT INTO `wp_postmeta` VALUES (42851,1239,'tab_3_slide_intro_image','300');
INSERT INTO `wp_postmeta` VALUES (42852,1239,'_tab_3_slide_intro_image','field_5e8ca5c579bc1');
INSERT INTO `wp_postmeta` VALUES (42853,1239,'tab_3_impact_message','Stem cells are specialized human cells with the ability to transform to many cell types from muscle cells to brain cells. Their amazing potential for healing has made them popular in mainstream and medical media.');
INSERT INTO `wp_postmeta` VALUES (42854,1239,'_tab_3_impact_message','field_5e8ca64579bc4');
INSERT INTO `wp_postmeta` VALUES (42855,1239,'tab_3_impact_background_image','1021');
