INSERT INTO `wp_postmeta` VALUES (42892,1239,'_tab_1_scientific_info_flex_2_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (42893,1239,'tab_1_scientific_info_flex_2_scientific_block_content_0_scientific_text','In this study, we compared heart rates and blood pressure values in 7 sessions with different leg pressures applied, ranging from <strong>0 mmHg</strong> to <strong>85 mmHg</strong>.');
