INSERT INTO `wp_postmeta` VALUES (43796,1242,'_tab_1_scientific_info_flex','field_5e8ca67a79bc6');
INSERT INTO `wp_postmeta` VALUES (43797,1242,'tab_1','');
INSERT INTO `wp_postmeta` VALUES (43798,1242,'_tab_1','field_5e8ca6cb504a7');
INSERT INTO `wp_postmeta` VALUES (43799,1242,'tab_2_slide_intro_name','Health');
INSERT INTO `wp_postmeta` VALUES (43800,1242,'_tab_2_slide_intro_name','field_5e8ca63579bc3');
INSERT INTO `wp_postmeta` VALUES (43801,1242,'tab_2_slide_intro_paragraph','At any age, you deserve to feel great — and that feeling should come easy. We’ve partnered with various individuals, from US war veterans to independent living seniors, to understand the benefits of Vasper when it comes to sleep and emotional well-being. Our <a href=\"#safety-assessments\">safety study</a> has assured us that any person ranging in age and physical ability can use our system. Using our non-invasive technology, our goal is to fully comprehend how individuals at any age or life experience can engage their body to achieve optimal energy levels &amp; wellness. Some of our strongest evidence suggests that Vasper can <a href=\"#improved-sleep-quality\">improve sleep quality</a>. Though there may be many explanations for this, we have found that Vasper <a href=\"#hormonal-response:-growth-hormone,-cortisol,-and-testosterone\">decreases stress levels</a> specifically at night.');
INSERT INTO `wp_postmeta` VALUES (43802,1242,'_tab_2_slide_intro_paragraph','field_5e8ca60479bc2');
INSERT INTO `wp_postmeta` VALUES (43803,1242,'tab_2_slide_intro_image','299');
INSERT INTO `wp_postmeta` VALUES (43804,1242,'_tab_2_slide_intro_image','field_5e8ca5c579bc1');
INSERT INTO `wp_postmeta` VALUES (43805,1242,'tab_2_impact_message','Sleep is the most important biological currency in our body. Receiving quality sleep can improve mood, weight, and even immune function.');
INSERT INTO `wp_postmeta` VALUES (43806,1242,'_tab_2_impact_message','field_5e8ca64579bc4');
INSERT INTO `wp_postmeta` VALUES (43807,1242,'tab_2_impact_background_image','1020');
