INSERT INTO `wp_postmeta` VALUES (44489,1244,'tab_1_scientific_info_flex_1_scientific_title','Testosterone Increase');
INSERT INTO `wp_postmeta` VALUES (44490,1244,'_tab_1_scientific_info_flex_1_scientific_title','field_5e8ce3c26a59d');
INSERT INTO `wp_postmeta` VALUES (44491,1244,'tab_1_scientific_info_flex_1_scientific_block_content_0_scientific_text','And our hormone investigation didn’t stop there. Testosterone is a key hormone that is involved in regulating muscle growth, bone density, fat metabolism, and mood in both men and women. We explored this hormone with five professional baseball players in 8 Vasper sessions over 2 weeks. 80% saw an increase in free testosterone levels, with an average increase of 132% across all participants.');
INSERT INTO `wp_postmeta` VALUES (44492,1244,'_tab_1_scientific_info_flex_1_scientific_block_content_0_scientific_text','field_5e8ce3ce6a5a0');
INSERT INTO `wp_postmeta` VALUES (44493,1244,'tab_1_scientific_info_flex_1_scientific_block_content_0_image_for_desktop','1026');
