INSERT INTO `wp_postmeta` VALUES (45790,1251,'_tab_1_scientific_info_flex_1_scientific_block_content','field_5e8ce3ce6a59f');
INSERT INTO `wp_postmeta` VALUES (45791,1251,'tab_1_scientific_info_flex_2_background_image','1023');
INSERT INTO `wp_postmeta` VALUES (45792,1251,'_tab_1_scientific_info_flex_2_background_image','field_5e8ce6646eeca');
INSERT INTO `wp_postmeta` VALUES (45793,1251,'tab_1_scientific_info_flex_2_scientific_title','Safety Assessment');
INSERT INTO `wp_postmeta` VALUES (45794,1251,'_tab_1_scientific_info_flex_2_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (45795,1251,'tab_1_scientific_info_flex_2_scientific_block_content_0_scientific_text','In this study, we took 20 healthy participants to assess the safety of Vasper on the cardiovascular system. We compared heart rates and blood pressure values in 7 sessions with different leg pressures applied, ranging from <strong>0 mmHg</strong> to <strong>85 mmHg</strong>.');
INSERT INTO `wp_postmeta` VALUES (45796,1251,'_tab_1_scientific_info_flex_2_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
INSERT INTO `wp_postmeta` VALUES (45797,1251,'tab_1_scientific_info_flex_2_scientific_block_content_0_image_for_desktop','1064');
INSERT INTO `wp_postmeta` VALUES (45798,1251,'_tab_1_scientific_info_flex_2_scientific_block_content_0_image_for_desktop','field_5e8d00b3d162a');
INSERT INTO `wp_postmeta` VALUES (45799,1251,'tab_1_scientific_info_flex_2_scientific_block_content_0_image_for_mobile','');
INSERT INTO `wp_postmeta` VALUES (45800,1251,'_tab_1_scientific_info_flex_2_scientific_block_content_0_image_for_mobile','field_5e8ce36d6a59b');
INSERT INTO `wp_postmeta` VALUES (45801,1251,'tab_1_scientific_info_flex_2_scientific_block_content_1_scientific_text','There was no significant difference in heart rate or blood pressure when comparing a session without Vasper’s cooling cuffs to a session with the cuffs at our allowed range of pressure (0-80mmHg). The study can be read in full here in the Journal of Exercise Physiology.');
INSERT INTO `wp_postmeta` VALUES (45802,1251,'_tab_1_scientific_info_flex_2_scientific_block_content_1_scientific_text','field_5e8ce3326a59a');
