INSERT INTO `wp_postmeta` VALUES (46510,1253,'_tab_2_scientific_info_flex_0_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
INSERT INTO `wp_postmeta` VALUES (46511,1253,'tab_2_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','1048');
INSERT INTO `wp_postmeta` VALUES (46512,1253,'_tab_2_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','field_5e8d00b3d162a');
