INSERT INTO `wp_postmeta` VALUES (46831,1254,'tab_2_scientific_info_flex_0_scientific_block_content_0_scientific_text','<h3>Hormonal Response: <span style=\"font-weight: normal; color: white;\">Growth Hormone, Cortisol, and Testosterone</span></h3> ');
INSERT INTO `wp_postmeta` VALUES (46832,1254,'_tab_2_scientific_info_flex_0_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
INSERT INTO `wp_postmeta` VALUES (46833,1254,'tab_2_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','1048');
INSERT INTO `wp_postmeta` VALUES (46834,1254,'_tab_2_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','field_5e8d00b3d162a');
INSERT INTO `wp_postmeta` VALUES (46835,1254,'tab_2_scientific_info_flex_0_scientific_block_content_0_image_for_mobile','');
INSERT INTO `wp_postmeta` VALUES (46836,1254,'_tab_2_scientific_info_flex_0_scientific_block_content_0_image_for_mobile','field_5e8ce36d6a59b');
INSERT INTO `wp_postmeta` VALUES (46837,1254,'tab_2_scientific_info_flex_0_scientific_block_content_1_scientific_text','This pilot study was designed after feedback from our clients, who reported anecdotally that Vasper had a unique ability to heighten certain beneficial hormones while having the opposite response in other stress hormones. The two categories of hormones we considered were <strong>anabolic hormones</strong> and <strong>catabolic hormones</strong>, which work in opposition to each other to build and repair (anabolic) and breakdown (catabolic). Our study with Veterans revealed that people were experiencing a better quality sleep as a result of using Vasper. Our pilot study suggests that one reason for this better quality of sleep could be the observed effect of reduced night-time cortisol.\r\n\r\nIn this Pilot Trial, Vasper investigated the hormone response from 10-20 Vasper sessions over 4-6 weeks. This trial demonstrated that Vasper was able to release the beneficial muscle-building response of:');
