INSERT INTO `wp_postmeta` VALUES (47699,1257,'tab_3_scientific_info_flex','a:3:{i:0;s:27:\"block_with_background_image\";i:1;s:26:\"block_with_blue_background\";i:2;s:27:\"block_with_background_image\";}');
