INSERT INTO `wp_postmeta` VALUES (48001,1258,'tab_1_scientific_info_flex','a:3:{i:0;s:27:\"block_with_background_image\";i:1;s:26:\"block_with_blue_background\";i:2;s:27:\"block_with_background_image\";}');
INSERT INTO `wp_postmeta` VALUES (48002,1258,'_tab_1_scientific_info_flex','field_5e8ca67a79bc6');
INSERT INTO `wp_postmeta` VALUES (48003,1258,'tab_1','');
INSERT INTO `wp_postmeta` VALUES (48004,1258,'_tab_1','field_5e8ca6cb504a7');
INSERT INTO `wp_postmeta` VALUES (48005,1258,'tab_2_slide_intro_name','Health');
INSERT INTO `wp_postmeta` VALUES (48006,1258,'_tab_2_slide_intro_name','field_5e8ca63579bc3');
INSERT INTO `wp_postmeta` VALUES (48007,1258,'tab_2_slide_intro_paragraph','At any age, you deserve to feel great — and that feeling should come easy. From US war veterans to independent living seniors, we’ve partnered with various individuals to understand the benefits of Vasper when it comes to sleep and emotional well-being. Our <a href=\"#safety-assessments\">safety study</a> has assured us that any person ranging in age and physical ability can use our system. Using our non-invasive technology, our goal is to fully comprehend how individuals at any age or life experience can engage their body to achieve optimal energy levels &amp; wellness. Some of our strongest evidence suggests that Vasper can <a href=\"#improved-sleep-quality\">improve sleep quality</a>. Though there may be many explanations for this, we have found that Vasper <a href=\"#hormonal-response:-growth-hormone,-cortisol,-and-testosterone\">decreases stress levels</a> specifically at night.');
INSERT INTO `wp_postmeta` VALUES (48008,1258,'_tab_2_slide_intro_paragraph','field_5e8ca60479bc2');
INSERT INTO `wp_postmeta` VALUES (48009,1258,'tab_2_slide_intro_image','1245');
INSERT INTO `wp_postmeta` VALUES (48010,1258,'_tab_2_slide_intro_image','field_5e8ca5c579bc1');
INSERT INTO `wp_postmeta` VALUES (48011,1258,'tab_2_impact_message','SLEEP IS THE MOST IMPORTANT BIOLOGICAL CURRENCY IN OUR BODY. RECEIVING QUALITY SLEEP CAN IMPROVE MOOD, WEIGHT, AND EVEN IMMUNE FUNCTION.');
INSERT INTO `wp_postmeta` VALUES (48012,1258,'_tab_2_impact_message','field_5e8ca64579bc4');
INSERT INTO `wp_postmeta` VALUES (48013,1258,'tab_2_impact_background_image','1020');
INSERT INTO `wp_postmeta` VALUES (48014,1258,'_tab_2_impact_background_image','field_5e8ca66d79bc5');
INSERT INTO `wp_postmeta` VALUES (48015,1258,'tab_2_scientific_info_flex','a:4:{i:0;s:27:\"block_with_background_image\";i:1;s:26:\"block_with_blue_background\";i:2;s:27:\"block_with_background_image\";i:3;s:26:\"block_with_blue_background\";}');
INSERT INTO `wp_postmeta` VALUES (48016,1258,'_tab_2_scientific_info_flex','field_5e8ca67a79bc6');
INSERT INTO `wp_postmeta` VALUES (48017,1258,'tab_2','');
INSERT INTO `wp_postmeta` VALUES (48018,1258,'_tab_2','field_5e8ce72c94c28');
INSERT INTO `wp_postmeta` VALUES (48019,1258,'tab_3_slide_intro_name','Rehabilitation');
INSERT INTO `wp_postmeta` VALUES (48020,1258,'_tab_3_slide_intro_name','field_5e8ca63579bc3');
INSERT INTO `wp_postmeta` VALUES (48021,1258,'tab_3_slide_intro_paragraph','The health benefits from Vasper are numerous and broad. Our work with a wide spectrum of clients has taught us that our system can be used to alleviate symptoms and provide support for a number of diseases and conditions. We’ve partnered with top hospitals and clinics to investigate the potential benefits of Vasper use in different clinical settings. Though the specific mechanisms for how Vasper helps in the body are still being investigated, many of our studies have shown that Vasper can help with a multitude of illnesses and conditions. A randomized control trial found that Vasper <a href=\"#neurological-benefits\">helps neurologically</a>. One possible reason we see improvements in the nervous and musculoskeletal systems is the <a href=\"#stem-cell-recruitment\">activation of stem cells</a> in the body after a Vasper session. Lastly, our work with Veterans has taught us that Vasper can help manage trauma-related stress, <a href=\"#emotional-and-energy-improvement\">increase sleep quality</a>, and <a href=\"#emotional-and-energy-improvement\">improve emotional wellbeing and energy levels</a>.');
INSERT INTO `wp_postmeta` VALUES (48022,1258,'_tab_3_slide_intro_paragraph','field_5e8ca60479bc2');
INSERT INTO `wp_postmeta` VALUES (48023,1258,'tab_3_slide_intro_image','300');
INSERT INTO `wp_postmeta` VALUES (48024,1258,'_tab_3_slide_intro_image','field_5e8ca5c579bc1');
INSERT INTO `wp_postmeta` VALUES (48025,1258,'tab_3_impact_message','Stem cells are specialized human cells with the ability to transform to many cell types from muscle cells to brain cells. Their amazing potential for healing has made them popular in mainstream and medical media.');
INSERT INTO `wp_postmeta` VALUES (48026,1258,'_tab_3_impact_message','field_5e8ca64579bc4');
INSERT INTO `wp_postmeta` VALUES (48027,1258,'tab_3_impact_background_image','1021');
INSERT INTO `wp_postmeta` VALUES (48028,1258,'_tab_3_impact_background_image','field_5e8ca66d79bc5');
INSERT INTO `wp_postmeta` VALUES (48029,1258,'tab_3_scientific_info_flex','a:3:{i:0;s:27:\"block_with_background_image\";i:1;s:26:\"block_with_blue_background\";i:2;s:27:\"block_with_background_image\";}');
INSERT INTO `wp_postmeta` VALUES (48030,1258,'_tab_3_scientific_info_flex','field_5e8ca67a79bc6');
INSERT INTO `wp_postmeta` VALUES (48031,1258,'tab_3','');
INSERT INTO `wp_postmeta` VALUES (48032,1258,'_tab_3','field_5e8ce74d94c29');
INSERT INTO `wp_postmeta` VALUES (48033,1258,'tab_1_scientific_info_flex_0_background_image','1213');
INSERT INTO `wp_postmeta` VALUES (48034,1258,'_tab_1_scientific_info_flex_0_background_image','field_5e8ce6646eeca');
INSERT INTO `wp_postmeta` VALUES (48035,1258,'tab_1_scientific_info_flex_0_scientific_title','Performance Increase');
INSERT INTO `wp_postmeta` VALUES (48036,1258,'_tab_1_scientific_info_flex_0_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (48037,1258,'tab_1_scientific_info_flex_0_scientific_block_content_0_scientific_text','Vasper worked with San Jose Sharks Strength and Conditioning Coach Mike Potenza to work with the 131st ParaRescue Squadron to assess hormone levels and performance results. ParaRescuemen are elite military operators, who specialize in medical rescue in war zones and remote areas. Due to the stress and length of their deployments, higher cortisol levels, sleep disturbances, and the resulting effects on their performance were a top concern.\r\n\r\n\r\n<span class=\"text-white d-block\" style=\"text-transform: uppercase; margin-top: 65px;\">Vasper Pararescue trial: Performance results</span>\r\nThe difference didn’t just show in their hormones - the Vasper group performed better on typical military performance tests, such as:');
INSERT INTO `wp_postmeta` VALUES (48038,1258,'_tab_1_scientific_info_flex_0_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
