INSERT INTO `wp_postmeta` VALUES (48461,1259,'tab_2_scientific_info_flex_0_background_image','1246');
INSERT INTO `wp_postmeta` VALUES (48462,1259,'_tab_2_scientific_info_flex_0_background_image','field_5e8ce6646eeca');
INSERT INTO `wp_postmeta` VALUES (48463,1259,'tab_2_scientific_info_flex_0_scientific_title','');
INSERT INTO `wp_postmeta` VALUES (48464,1259,'_tab_2_scientific_info_flex_0_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (48465,1259,'tab_2_scientific_info_flex_0_scientific_block_content_0_scientific_text','<h3>Hormonal Response: <span style=\"font-weight: normal; color: white;\">Growth Hormone, Cortisol, and Testosterone</span></h3>\r\n\r\nIn this Pilot Trial, Vasper investigated the hormone response from 10-20 Vasper sessions over 4-6 weeks. This trial demonstrated that Vasper was able to release the beneficial muscle-building response of:');
