INSERT INTO `wp_postmeta` VALUES (48621,1260,'tab_3_children_top_paragraph_1','The Cantu Concussion Center at Emerson Hospital is one of the leading centers of concussion clinical treatment and research. Dr. Robert Cantu with Dr. Yi-Ning Wu designed a study to examine Vasper’s potential to help with concussion treatment.');
