INSERT INTO `wp_postmeta` VALUES (48738,1260,'_tab_1_scientific_info_flex_2_scientific_block_content','field_5e8ce38f6a59c');
INSERT INTO `wp_postmeta` VALUES (48739,1260,'tab_3_scientific_info_flex_0_background_image','1032');
