INSERT INTO `wp_postmeta` VALUES (49059,1261,'tab_1_scientific_info_flex_2_scientific_block_content_0_image_for_mobile','');
INSERT INTO `wp_postmeta` VALUES (49060,1261,'_tab_1_scientific_info_flex_2_scientific_block_content_0_image_for_mobile','field_5e8ce36d6a59b');
INSERT INTO `wp_postmeta` VALUES (49061,1261,'tab_1_scientific_info_flex_2_scientific_block_content_1_scientific_text','There was no significant difference in heart rate or blood pressure when comparing a session without Vasper’s cooling cuffs to a session with the cuffs at our allowed range of pressure (0-80mmHg). The study can be read in full here in the Journal of Exercise Physiology.');
INSERT INTO `wp_postmeta` VALUES (49062,1261,'_tab_1_scientific_info_flex_2_scientific_block_content_1_scientific_text','field_5e8ce3326a59a');
