INSERT INTO `wp_postmeta` VALUES (49405,1263,'tab_3_scientific_info_flex_0_scientific_block_content_0_scientific_text','ImPACT, BESS, King-Devick Test, SAC improved after the intervention in both groups but there was no significant difference between two groups.');
INSERT INTO `wp_postmeta` VALUES (49406,1263,'_tab_3_scientific_info_flex_0_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
INSERT INTO `wp_postmeta` VALUES (49407,1263,'tab_3_scientific_info_flex_0_scientific_block_content_0_image_for_desktop','1033');
