INSERT INTO `wp_postmeta` VALUES (49654,1264,'_tab_1_scientific_info_flex','field_5e8ca67a79bc6');
INSERT INTO `wp_postmeta` VALUES (49655,1264,'tab_1','');
INSERT INTO `wp_postmeta` VALUES (49656,1264,'_tab_1','field_5e8ca6cb504a7');
INSERT INTO `wp_postmeta` VALUES (49657,1264,'tab_2_slide_intro_name','Health');
INSERT INTO `wp_postmeta` VALUES (49658,1264,'_tab_2_slide_intro_name','field_5e8ca63579bc3');
INSERT INTO `wp_postmeta` VALUES (49659,1264,'tab_2_slide_intro_paragraph','At any age, you deserve to feel great — and that feeling should come easy. From US war veterans to independent living seniors, we’ve partnered with various individuals to understand the benefits of Vasper when it comes to sleep and emotional well-being. Our <a href=\"#safety-assessments\">safety study</a> has assured us that any person ranging in age and physical ability can use our system. Using our non-invasive technology, our goal is to fully comprehend how individuals at any age or life experience can engage their body to achieve optimal energy levels &amp; wellness. Some of our strongest evidence suggests that Vasper can <a href=\"#improved-sleep-quality\">improve sleep quality</a>. Though there may be many explanations for this, we have found that Vasper <a href=\"#hormonal-response:-growth-hormone,-cortisol,-and-testosterone\">decreases stress levels</a> specifically at night.');
INSERT INTO `wp_postmeta` VALUES (49660,1264,'_tab_2_slide_intro_paragraph','field_5e8ca60479bc2');
INSERT INTO `wp_postmeta` VALUES (49661,1264,'tab_2_slide_intro_image','1245');
INSERT INTO `wp_postmeta` VALUES (49662,1264,'_tab_2_slide_intro_image','field_5e8ca5c579bc1');
INSERT INTO `wp_postmeta` VALUES (49663,1264,'tab_2_impact_message','SLEEP IS THE MOST IMPORTANT BIOLOGICAL CURRENCY IN OUR BODY. RECEIVING QUALITY SLEEP CAN IMPROVE MOOD, WEIGHT, AND EVEN IMMUNE FUNCTION.');
INSERT INTO `wp_postmeta` VALUES (49664,1264,'_tab_2_impact_message','field_5e8ca64579bc4');
