INSERT INTO `wp_postmeta` VALUES (50045,1265,'tab_1_scientific_info_flex_2_scientific_title','Safety Assessment');
INSERT INTO `wp_postmeta` VALUES (50046,1265,'_tab_1_scientific_info_flex_2_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (50047,1265,'tab_1_scientific_info_flex_2_scientific_block_content_0_scientific_text','In this study, we took 20 healthy participants to assess the safety of Vasper on the cardiovascular system. We compared heart rates and blood pressure values in 7 sessions with different leg pressures applied, ranging from <strong>0 mmHg</strong> to <strong>85 mmHg</strong>.');
INSERT INTO `wp_postmeta` VALUES (50048,1265,'_tab_1_scientific_info_flex_2_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
INSERT INTO `wp_postmeta` VALUES (50049,1265,'tab_1_scientific_info_flex_2_scientific_block_content_0_image_for_desktop','1064');
