INSERT INTO `wp_postmeta` VALUES (50937,1269,'tab_2_scientific_info_flex','a:3:{i:0;s:27:\"block_with_background_image\";i:1;s:26:\"block_with_blue_background\";i:2;s:27:\"block_with_background_image\";}');
INSERT INTO `wp_postmeta` VALUES (50938,1269,'_tab_2_scientific_info_flex','field_5e8ca67a79bc6');
INSERT INTO `wp_postmeta` VALUES (50939,1269,'tab_2','');
INSERT INTO `wp_postmeta` VALUES (50940,1269,'_tab_2','field_5e8ce72c94c28');
INSERT INTO `wp_postmeta` VALUES (50941,1269,'tab_3_slide_intro_name','Rehabilitation');
INSERT INTO `wp_postmeta` VALUES (50942,1269,'_tab_3_slide_intro_name','field_5e8ca63579bc3');
INSERT INTO `wp_postmeta` VALUES (50943,1269,'tab_3_slide_intro_paragraph','The health benefits from Vasper are numerous and broad. Our work with a wide spectrum of clients has taught us that our system can be used to alleviate symptoms and provide support for a number of diseases and conditions. We’ve partnered with top hospitals and clinics to investigate the potential benefits of Vasper use in different clinical settings. Though the specific mechanisms for how Vasper helps in the body are still being investigated, many of our studies have shown that Vasper can help with a multitude of illnesses and conditions. A randomized control trial found that Vasper <a href=\"#neurological-benefits\">helps neurologically</a>. One possible reason we see improvements in the nervous and musculoskeletal systems is the <a href=\"#stem-cell-recruitment\">activation of stem cells</a> in the body after a Vasper session. Lastly, our work with Veterans has taught us that Vasper can help manage trauma-related stress, <a href=\"#emotional-and-energy-improvement\">increase sleep quality</a>, and <a href=\"#emotional-and-energy-improvement\">improve emotional wellbeing and energy levels</a>.');
INSERT INTO `wp_postmeta` VALUES (50944,1269,'_tab_3_slide_intro_paragraph','field_5e8ca60479bc2');
INSERT INTO `wp_postmeta` VALUES (50945,1269,'tab_3_slide_intro_image','1267');
INSERT INTO `wp_postmeta` VALUES (50946,1269,'_tab_3_slide_intro_image','field_5e8ca5c579bc1');
INSERT INTO `wp_postmeta` VALUES (50947,1269,'tab_3_impact_message','STEM CELLS ARE SPECIALIZED HUMAN CELLS WITH THE ABILITY TO TRANSFORM TO MANY CELL TYPES FROM MUSCLE CELLS TO BRAIN CELLS. THEIR AMAZING POTENTIAL FOR HEALING HAS MADE THEM POPULAR IN MAINSTREAM AND MEDICAL MEDIA.');
INSERT INTO `wp_postmeta` VALUES (50948,1269,'_tab_3_impact_message','field_5e8ca64579bc4');
INSERT INTO `wp_postmeta` VALUES (50949,1269,'tab_3_impact_background_image','1021');
