INSERT INTO `wp_postmeta` VALUES (51597,1272,'tab_3_impact_message','STEM CELLS ARE SPECIALIZED HUMAN CELLS WITH THE ABILITY TO TRANSFORM TO MANY CELL TYPES FROM MUSCLE CELLS TO BRAIN CELLS. THEIR AMAZING POTENTIAL FOR HEALING HAS MADE THEM POPULAR IN MAINSTREAM AND MEDICAL MEDIA.');
