INSERT INTO `wp_postmeta` VALUES (51715,1272,'tab_2_scientific_info_flex_1_scientific_title','Improved Sleep Quality');
INSERT INTO `wp_postmeta` VALUES (51716,1272,'_tab_2_scientific_info_flex_1_scientific_title','field_5e8ce3c26a59d');
INSERT INTO `wp_postmeta` VALUES (51717,1272,'tab_2_scientific_info_flex_1_scientific_block_content_0_scientific_text','A pilot trial was conducted to determine the potential effects of the Vasper exercise system on markers of physical and emotional function \r\nin a ample of 14 US armed forces veterans from the Warrior Evolved Veteran Rehabilitation Facility in Colorado Springs. Participants completed 24 Vasper sessions over a 6-week trial period. Sleep quality was measure pre-and post-trial using the Pittsburg Sleep Quality Index (PSQI) questionnaire. At post-evaluation 71% of participants reported a better score of the PSQI, indicating a significant improvement in sleep quality at the end of the trial period. \r\n\r\nSubjective perception of energy and fatigue was also measured pre-and post-trial using the SF-36 quality of life questionnaire. 71% (n=10) of participants reported higher levels of energy following the trial period.');
