INSERT INTO `wp_postmeta` VALUES (51819,1273,'tab_1_children_top_paragraph_2','You’ve probably heard about stem cells in many different contexts. Stem cells are used in surgery, rehabilitation, medical devices, outpatient treatments, cosmetology, and dermatology.');
