INSERT INTO `wp_postmeta` VALUES (51929,1273,'tab_1_scientific_info_flex_0_scientific_title','Performance Increase');
INSERT INTO `wp_postmeta` VALUES (51930,1273,'_tab_1_scientific_info_flex_0_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (51931,1273,'tab_1_scientific_info_flex_0_scientific_block_content_0_scientific_text','Vasper worked with San Jose Sharks Strength and Conditioning Coach Mike Potenza to work with the 131st ParaRescue Squadron to assess hormone levels and performance results. ParaRescuemen are elite military operators, who specialize in medical rescue in war zones and remote areas. Due to the stress and length of their deployments, higher cortisol levels, sleep disturbances, and the resulting effects on their performance were a top concern.\r\n\r\n\r\n<span class=\"text-white d-block\" style=\"text-transform: uppercase; margin-top: 65px;\"><em>Vasper Pararescue trial: Performance results</em></span>\r\nThe difference didn’t just show in their hormones - the Vasper group performed better on typical military performance tests, such as:');
INSERT INTO `wp_postmeta` VALUES (51932,1273,'_tab_1_scientific_info_flex_0_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
