INSERT INTO `wp_postmeta` VALUES (52136,1274,'_tab_1_children_tab_name_1','field_5db89b89740ef');
INSERT INTO `wp_postmeta` VALUES (52137,1274,'tab_1_children_top_paragraph_1','Hormones are your body’s systemic signaling molecules and are released in different areas of the body and move through the circulatory system to regulate your body’s function and behavior. Hormones affect the body in many different ways and have significant impacts on function, form, and feel. ');
INSERT INTO `wp_postmeta` VALUES (52138,1274,'_tab_1_children_top_paragraph_1','field_5db89bc1740f3');
INSERT INTO `wp_postmeta` VALUES (52139,1274,'tab_1_children_tab_name_2','');
INSERT INTO `wp_postmeta` VALUES (52140,1274,'_tab_1_children_tab_name_2','field_5db89ba9740f1');
INSERT INTO `wp_postmeta` VALUES (52141,1274,'tab_1_children_top_paragraph_2','You’ve probably heard about stem cells in many different contexts. Stem cells are used in surgery, rehabilitation, medical devices, outpatient treatments, cosmetology, and dermatology.');
INSERT INTO `wp_postmeta` VALUES (52142,1274,'_tab_1_children_top_paragraph_2','field_5db89beb740f6');
