INSERT INTO `wp_postmeta` VALUES (52249,1274,'tab_1_scientific_info_flex_0_background_image','1213');
INSERT INTO `wp_postmeta` VALUES (52250,1274,'_tab_1_scientific_info_flex_0_background_image','field_5e8ce6646eeca');
INSERT INTO `wp_postmeta` VALUES (52251,1274,'tab_1_scientific_info_flex_0_scientific_title','Performance Increase');
INSERT INTO `wp_postmeta` VALUES (52252,1274,'_tab_1_scientific_info_flex_0_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (52253,1274,'tab_1_scientific_info_flex_0_scientific_block_content_0_scientific_text','Vasper worked with San Jose Sharks Strength and Conditioning Coach Mike Potenza to work with the 131st ParaRescue Squadron to assess hormone levels and performance results. ParaRescuemen are elite military operators, who specialize in medical rescue in war zones and remote areas. Due to the stress and length of their deployments, higher cortisol levels, sleep disturbances, and the resulting effects on their performance were a top concern.\r\n\r\n\r\n<span class=\"text-white d-block\" style=\"text-transform: uppercase; margin-top: 65px;\"><em>Vasper Pararescue trial: Performance results</em></span>\r\nThe difference didn’t just show in their hormones - the Vasper group performed better on typical military performance tests, such as:');
INSERT INTO `wp_postmeta` VALUES (52254,1274,'_tab_1_scientific_info_flex_0_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
INSERT INTO `wp_postmeta` VALUES (52255,1274,'tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_mobile','1029');
