INSERT INTO `wp_postmeta` VALUES (52753,1275,'tab_3_scientific_info_flex_1_scientific_block_content_2_results_disclaimer','Environmental Mobilization Of Hematopoetic Stem Cells With Exercise, Compression, And Cooling\r\nby Adam W. Anz, Danielle R. Hansen, Christopher S. Warrell, Ronna S. Parsa, Hillary A. Plummer, Jan M. Stelly, Nicole K. Rendos');
INSERT INTO `wp_postmeta` VALUES (52754,1275,'_tab_3_scientific_info_flex_1_scientific_block_content_2_results_disclaimer','field_5f921baa39756');
INSERT INTO `wp_postmeta` VALUES (52755,1275,'tab_3_scientific_info_flex_3_scientific_title','Improving Strength and Balance in Seniors');
INSERT INTO `wp_postmeta` VALUES (52756,1275,'_tab_3_scientific_info_flex_3_scientific_title','field_5e8ce3c26a59d');
INSERT INTO `wp_postmeta` VALUES (52757,1275,'tab_3_scientific_info_flex_3_scientific_block_content_0_scientific_text','Twenty seven participants between the ages of 60 and 90 completed a 12-session fall prevention trial on the Vasper exercise system at the Kahala Nui Senior Living Home. A pre-and post-training evaluation was completed by a physical therapist and included test of <strong>knee extension strength</strong>, a <strong>Berg balance test</strong>, and a <strong>10XSTS test</strong>.\r\n\r\nResults demonstrate a 17% average improvement in balance, and average increases of knee extension strength by 11 pounds of force, and a 6 second average time improvement in the 10XSTS test. 63% of participants reported a subjective improvement in strength, while 53% reported an improvement in balance after the trial period. ');
INSERT INTO `wp_postmeta` VALUES (52758,1275,'_tab_3_scientific_info_flex_3_scientific_block_content_0_scientific_text','field_5e8ce3ce6a5a0');
