INSERT INTO `wp_postmeta` VALUES (52975,1276,'tab_3_scientific_info_flex_2_scientific_title','Emotional and Energy Improvement');
INSERT INTO `wp_postmeta` VALUES (52976,1276,'_tab_3_scientific_info_flex_2_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (52977,1276,'tab_3_scientific_info_flex_2_scientific_block_content_0_scientific_text','A pilot trial was conducted to determine the potential effects of the Vasper exercise system on markers of physical and emotional function \r\nin a ample of 14 US armed forces veterans from the <strong>Warrior Evolved Veteran Rehabilitation Facility</strong> in Colorado Springs. Participants completed 24 Vasper sessions over a 6-week trial period. Sleep quality was measure pre-and post-trial using the <strong>Pittsburg Sleep Quality Index</strong> (PSQI) questionnaire. At post-evaluation 71% of participants reported a better score of the PSQI, indicating a significant improvement in sleep quality at the end of the trial period. \r\n\r\nSubjective perception of energy and fatigue was also measured pre-and post-trial using the SF-36 quality of life questionnaire. 71% (n=10) of participants reported higher levels of energy following the trial period. ');
INSERT INTO `wp_postmeta` VALUES (52978,1276,'_tab_3_scientific_info_flex_2_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
