INSERT INTO `wp_postmeta` VALUES (53060,1276,'_tab_3_scientific_info_flex_1_scientific_block_content_1_results_disclaimer','field_5f921baa39756');
INSERT INTO `wp_postmeta` VALUES (53061,1276,'tab_2_scientific_info_flex_0_scientific_block_content_2_scientific_text','This pilot study was designed after feedback from our clients, who reported anecdotally that Vasper had a unique ability to heighten certain beneficial hormones while having the opposite response in other stress hormones. Our study with Veterans revealed that people were experiencing a better quality sleep as a result of using Vasper. Our pilot study suggests that one reason for this better quality of sleep could be the observed effect of reduced night-time cortisol.');
INSERT INTO `wp_postmeta` VALUES (53062,1276,'_tab_2_scientific_info_flex_0_scientific_block_content_2_scientific_text','field_5e8ce3326a59a');
