INSERT INTO `wp_postmeta` VALUES (53529,1278,'tab_3_impact_message','STEM CELLS ARE SPECIALIZED HUMAN CELLS WITH THE ABILITY TO TRANSFORM TO MANY CELL TYPES FROM MUSCLE CELLS TO BRAIN CELLS. THEIR AMAZING POTENTIAL FOR HEALING HAS MADE THEM POPULAR IN MAINSTREAM AND MEDICAL MEDIA.');
INSERT INTO `wp_postmeta` VALUES (53530,1278,'_tab_3_impact_message','field_5e8ca64579bc4');
