INSERT INTO `wp_postmeta` VALUES (53633,1278,'tab_2_scientific_info_flex_0_scientific_block_content_0_scientific_text','<h3>Hormonal Response: <span style=\"font-weight: normal; color: white;\">Growth Hormone, Cortisol, and Testosterone</span></h3>\r\n\r\nIn this Pilot Trial, Vasper investigated the hormone response from 10-20 Vasper sessions over 4-6 weeks. This trial demonstrated that Vasper was able to release the beneficial muscle-building response of:');
INSERT INTO `wp_postmeta` VALUES (53634,1278,'_tab_2_scientific_info_flex_0_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
