INSERT INTO `wp_postmeta` VALUES (54043,1279,'tab_3_scientific_info_flex_3_scientific_title','Improving Strength and Balance in Seniors');
INSERT INTO `wp_postmeta` VALUES (54044,1279,'_tab_3_scientific_info_flex_3_scientific_title','field_5e8ce3c26a59d');
INSERT INTO `wp_postmeta` VALUES (54045,1279,'tab_3_scientific_info_flex_3_scientific_block_content_0_scientific_text','Twenty seven participants between the ages of 60 and 90 completed a 12-session fall prevention trial on the Vasper exercise system at the Kahala Nui Senior Living Home. A pre-and post-training evaluation was completed by a physical therapist and included test of <strong>knee extension strength</strong>, a <strong>Berg balance test</strong>, and a <strong>10XSTS test</strong>.\r\n\r\nResults demonstrate a 17% average improvement in balance, and average increases of knee extension strength by 11 pounds of force, and a 6 second average time improvement in the 10XSTS test. 63% of participants reported a subjective improvement in strength, while 53% reported an improvement in balance after the trial period. ');
INSERT INTO `wp_postmeta` VALUES (54046,1279,'_tab_3_scientific_info_flex_3_scientific_block_content_0_scientific_text','field_5e8ce3ce6a5a0');
