INSERT INTO `wp_postmeta` VALUES (56240,1300,'_tab_1_children_tab_name_1','field_5db89b89740ef');
INSERT INTO `wp_postmeta` VALUES (56241,1300,'tab_1_children_top_paragraph_1','Hormones are your body’s systemic signaling molecules and are released in different areas of the body and move through the circulatory system to regulate your body’s function and behavior. Hormones affect the body in many different ways and have significant impacts on function, form, and feel. ');
INSERT INTO `wp_postmeta` VALUES (56242,1300,'_tab_1_children_top_paragraph_1','field_5db89bc1740f3');
INSERT INTO `wp_postmeta` VALUES (56243,1300,'tab_1_children_tab_name_2','');
INSERT INTO `wp_postmeta` VALUES (56244,1300,'_tab_1_children_tab_name_2','field_5db89ba9740f1');
INSERT INTO `wp_postmeta` VALUES (56245,1300,'tab_1_children_top_paragraph_2','You’ve probably heard about stem cells in many different contexts. Stem cells are used in surgery, rehabilitation, medical devices, outpatient treatments, cosmetology, and dermatology.');
