INSERT INTO `wp_postmeta` VALUES (56683,1302,'tab_1_scientific_info_flex_0_background_image','1213');
INSERT INTO `wp_postmeta` VALUES (56684,1302,'_tab_1_scientific_info_flex_0_background_image','field_5e8ce6646eeca');
INSERT INTO `wp_postmeta` VALUES (56685,1302,'tab_1_scientific_info_flex_0_scientific_title','Performance Increase');
INSERT INTO `wp_postmeta` VALUES (56686,1302,'_tab_1_scientific_info_flex_0_scientific_title','field_5e8ce31f6a599');
INSERT INTO `wp_postmeta` VALUES (56687,1302,'tab_1_scientific_info_flex_0_scientific_block_content_0_scientific_text','Vasper worked with San Jose Sharks Strength and Conditioning Coach Mike Potenza to work with the 131st ParaRescue Squadron to assess hormone levels and performance results. ParaRescuemen are elite military operators, who specialize in medical rescue in war zones and remote areas. Due to the stress and length of their deployments, higher cortisol levels, sleep disturbances, and the resulting effects on their performance were a top concern.\r\n\r\n<span class=\"text-white d-block\" style=\"text-transform: uppercase; margin-top: 65px;\"><em>Vasper Pararescue trial: Performance results</em></span>\r\nThe difference didn’t just show in their hormones - the Vasper group performed better on typical military performance tests, such as:');
INSERT INTO `wp_postmeta` VALUES (56688,1302,'_tab_1_scientific_info_flex_0_scientific_block_content_0_scientific_text','field_5e8ce3326a59a');
INSERT INTO `wp_postmeta` VALUES (56689,1302,'tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_mobile','1029');
INSERT INTO `wp_postmeta` VALUES (56690,1302,'_tab_1_scientific_info_flex_0_scientific_block_content_0_image_for_mobile','field_5e8ce36d6a59b');
