INSERT INTO `wp_posts` VALUES (614,1,'2020-02-12 19:47:00','2020-02-12 19:47:00','<!-- wp:paragraph -->\n<p>Brian Astell is a professional mountain bike racer, off-road triathlete, and NESTA certified triathlon and fitness nutrition coach. He competes professionally in many different disciplines including Xterra, Cyclocross, Endurance racing (100 mile mountain bike races), Cross country, Short track, and Enduro. </p>\n<!-- /wp:paragraph -->','INTERVIEW WITH BRIAN ASTELL, FOUNDER - TRAILWORKS','','inherit','closed','closed','','193-revision-v1','','','2020-02-12 19:47:00','2020-02-12 19:47:00','',193,'https://www.pulsecreative-clients.com/staging/vasper/archive/193-revision-v1/',0,'revision','',0);
